1	"use client";
2	
3	import { useState, type ReactNode } from "react";
4	import { Icon } from "@/components/nx/Icon";
5	import { fmtBytes } from "@/components/ui/primitives";
6	import { Card } from "./ui";
7	import type { VpsHeaderData } from "./types";
8	
9	/**
10	 * Resources: what this server has, what it could have, and what it is using.
11	 *
12	 * The concept's four independent sliders (CPU / Memory / Storage / Bandwidth)
13	 * are three tabs here, because only three of those four are separately
14	 * purchasable on this platform. CPU and memory move together — a plan is a
15	 * bundle and resize targets a plan id — so pretending they slide apart would
16	 * mean the Apply button silently snapping you to the nearest plan. Bandwidth is
17	 * not sold separately at all; it comes with the plan, so it is reported under
18	 * usage rather than offered as a control that does nothing.
19	 *
20	 * The usage rail on the right is the honest version of the concept's "Current
21	 * Usage": every bar is a real measurement, and an unmeasured one draws an em
22	 * dash rather than an empty bar, which would read as "nothing used".
23	 */
24	
25	type Key = "plan" | "storage" | "network";
26	
27	const TABS: { key: Key; label: string; icon: string }[] = [
28	  { key: "plan", label: "Plan", icon: "cpu" },
29	  { key: "storage", label: "Storage", icon: "database" },
30	  { key: "network", label: "Network", icon: "nodes" },
31	];
32	
33	function UsageBar({ label, used, total, unit, tone, note }: {
34	  label: string;
35	  used: number | null;
36	  total: number | null;
37	  unit: (n: number) => string;
38	  tone: string;
39	  note?: string;
40	}) {
41	  const known = used !== null && total !== null && total > 0;
42	  const p = known ? Math.max(0, Math.min(100, (used / total) * 100)) : 0;
43	  return (
44	    <div className="flex flex-col gap-1.5">
45	      <div className="flex items-baseline justify-between gap-2">
46	        <span className="text-[12px] text-tx-dim">{label}</span>
47	        {used === null ? (
48	          <span className="num text-[12px] font-bold text-tx-dim">—</span>
49	        ) : (
50	          <span className="num text-[12px] font-bold text-tx">
51	            {known ? `${Math.round(p)}%` : unit(used)}
52	          </span>
53	        )}
54	      </div>
55	      <span className="block h-[5px] w-full overflow-hidden rounded-full bg-[color-mix(in_srgb,var(--fg)_8%,transparent)]">
56	        {known && <span className="block h-full rounded-full" style={{ width: `${p}%`, background: tone }} />}
57	      </span>
58	      {(note || known) && (
59	        <span className="text-[10.5px] text-tx-faint">
60	          {note ?? `${unit(used!)} of ${unit(total!)}`}
61	        </span>
62	      )}
63	    </div>
64	  );
65	}
66	
67	export function VpsResourcesPanel({
68	  data, planSlider, storageControl, networkControl, planSummary,
69	}: {
70	  data: VpsHeaderData;
71	  planSlider: ReactNode;
72	  storageControl: ReactNode;
73	  networkControl: ReactNode;
74	  /** Name + spec of the plan in force, for the header pill. */
75	  planSummary: string;
76	}) {
77	  const [tab, setTab] = useState<Key>("plan");
78	
79	  const bwUsed = data.bandwidth.inBytes + data.bandwidth.outBytes;
80	  const bwAllowance = data.bandwidth.allowanceTB * 1024 ** 4;
81	
82	  return (
83	    <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_minmax(0,300px)]">
84	      <div className="flex min-w-0 flex-col gap-4">
85	        {/* ── header + sub-tabs ─────────────────────────────────────────── */}
86	        <div className="rounded-[16px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.5),rgba(2,7,20,.62))] p-4 sm:p-5">
87	          <div className="flex flex-wrap items-start justify-between gap-3">
88	            <div className="min-w-0">
89	              <h2 className="text-[17px] font-extrabold text-tx">Server resources</h2>
90	              <p className="mt-0.5 max-w-[72ch] text-[12.5px] leading-relaxed text-tx-faint">
91	                Change what this server is built from. Nothing is charged until you apply, and every
92	                figure below is the one you will actually be billed.
93	              </p>
94	            </div>
95	            <span className="flex-none rounded-[9px] border border-rim-hi bg-well px-3 py-1.5 text-[11.5px] font-bold text-tx-dim">
96	              Current: <span className="text-tx">{planSummary}</span>
97	            </span>
98	          </div>
99	
100	          <div className="mt-4 flex w-fit gap-1 rounded-[11px] border border-rim-soft bg-[rgba(4,10,28,.6)] p-1">
101	            {TABS.map((t) => {
102	              const on = tab === t.key;
103	              return (
104	                <button
105	                  key={t.key}
106	                  type="button"
107	                  onClick={() => setTab(t.key)}
108	                  className={
109	                    "inline-flex items-center gap-2 rounded-[8px] px-3.5 py-2 text-[12.5px] font-semibold transition " +
110	                    (on ? "bg-[color-mix(in_srgb,var(--fg)_9%,transparent)] text-tx" : "text-tx-dim hover:text-tx")
111	                  }
112	                >
113	                  <Icon name={t.icon} size={14} tone="inherit" className={on ? "text-tx" : "text-[#7f9ad0]"} />
114	                  {t.label}
115	                </button>
116	              );
117	            })}
118	          </div>
119	        </div>
120	
121	        {tab === "plan" && planSlider}
122	        {tab === "storage" && storageControl}
123	        {tab === "network" && networkControl}
124	      </div>
125	
126	      {/* ── the rail ──────────────────────────────────────────────────── */}
127	      <div className="flex min-w-0 flex-col gap-4">
128	        <Card title="Current usage">
129	          <div className="flex flex-col gap-3.5">
130	            <UsageBar
131	              label="CPU"
132	              used={data.live ? data.live.cpuPct : null}
133	              total={data.live ? 100 : null}
134	              unit={(n) => `${n.toFixed(1)}%`}
135	              tone="linear-gradient(90deg,#34d399,#5fd0ff)"
136	              note={data.live ? undefined : "Not reported by the hypervisor"}
137	            />
138	            <UsageBar
139	              label="Memory"
140	              used={data.live ? data.live.memBytes : null}
141	              total={data.live ? data.live.maxMemBytes : null}
142	              unit={fmtBytes}
143	              tone="linear-gradient(90deg,#7b3fef,#c33bea)"
144	              note={data.live ? undefined : "Not reported by the hypervisor"}
145	            />
146	            <UsageBar
147	              label="Bandwidth"
148	              used={bwUsed}
149	              total={bwAllowance}
150	              unit={fmtBytes}
151	              tone="linear-gradient(90deg,#f59e0b,#fb7185)"
152	            />
153	          </div>
154	          <p className="mt-3.5 border-t border-rim-soft pt-3 text-[11px] leading-relaxed text-tx-faint">
155	            Disk usage is read inside the guest and lives on Overview, next to its history.
156	          </p>
157	        </Card>
158	
159	        <Card title="Need something else?">
160	          <p className="text-[12.5px] leading-relaxed text-tx-dim">
161	            If none of the sizes fit, we can build one to your spec — the same per-vCPU and per-GB
162	            rates the catalogue is priced from.
163	          </p>
164	          <a
165	            href="/dashboard/support"
166	            className="mt-3 inline-flex items-center gap-2 rounded-[10px] border border-rim-hi bg-well px-3 py-2 text-[12.5px] font-semibold text-tx-body transition hover:border-[#8b5cff]/60 hover:text-tx"
167	          >
168	            <Icon name="chat" size={14} className="text-[#7f9ad0]" />
169	            Ask for a custom plan
170	          </a>
171	        </Card>
172	      </div>
173	    </div>
174	  );
175	}
