1	"use client";
2	
3	import { useEffect, useRef, useState, type ReactNode } from "react";
4	import { createPortal } from "react-dom";
5	import { Icon } from "@/components/nx/Icon";
6	
7	/**
8	 * The VPS command centre's component kit.
9	 *
10	 * One set of primitives for the whole panel, so Networking and Settings and
11	 * Overview cannot drift into three dialects again. Surfaces and motion live in
12	 * globals.css under the `.nxp` prefix; this file is the React side.
13	 *
14	 * Two rules worth keeping:
15	 *   1. Not everything needs a container. `Section` exists for content that
16	 *      wants a heading and rhythm WITHOUT a box — use it over `Panel` unless
17	 *      the content genuinely needs to be separated from what surrounds it.
18	 *   2. Anything that can be unknown takes `null`, not `0`. A tile handed null
19	 *      draws an em dash and a reason; it never draws a zero, because a zero is
20	 *      a measurement and "we could not ask" is not.
21	 */
22	
23	/* ── surfaces ─────────────────────────────────────────────────────────── */
24	
25	/** A bare titled block — heading, optional action, content. No box. */
26	export function Section({ title, sub, action, children, className = "" }: {
27	  title?: string; sub?: string; action?: ReactNode; children: ReactNode; className?: string;
28	}) {
29	  return (
30	    <section className={"flex min-w-0 flex-col " + className}>
31	      {(title || action) && (
32	        <div className="mb-3 flex flex-wrap items-end justify-between gap-3">
33	          <div className="min-w-0">
34	            {title && <h2 className="text-[13px] font-bold uppercase tracking-[0.14em] text-tx-faint">{title}</h2>}
35	            {sub && <p className="mt-1 text-[12.5px] leading-relaxed text-tx-dim">{sub}</p>}
36	          </div>
37	          {action}
38	        </div>
39	      )}
40	      {children}
41	    </section>
42	  );
43	}
44	
45	/** A contained panel. `interactive` adds the hover illumination. */
46	export function Panel({ title, action, children, className = "", interactive, pad = true, accent, icon, ink }: {
47	  title?: string; action?: ReactNode; children: ReactNode;
48	  className?: string; interactive?: boolean; pad?: boolean;
49	  /** A `--tone` hex for .card-glass — the per-card edge accent. */
50	  accent?: string;
51	  /** A bare glowing icon beside the title. No plate; the card carries the hue. */
52	  icon?: string;
53	  ink?: string;
54	}) {
55	  return (
56	    /* h-full + overflow-hidden so a card fills its bento cell and clips its own
57	       content instead of stretching the grid row. */
58	    /* `card card-glass` is the product's own liquid-glass surface — transparent
59	       pane, 24px backdrop blur, flat tinted border and a corner-tracing inner
60	       glow, with --tone setting the edge accent. Same treatment SupportView and
61	       WhatsNewView use. */
62	    <section
63	      className={`card card-glass ${interactive ? "card-i" : ""} flex h-full min-w-0 flex-col overflow-hidden p-0 ${className}`}
64	      style={accent ? ({ "--tone": accent } as React.CSSProperties) : undefined}
65	    >
66	      {title && (
67	        <div className="relative z-[1] flex flex-none items-center gap-2.5 border-b border-white/[0.07] px-4 py-2.5">
68	          {icon && <Icon name={icon} size={15} tone="inherit" className={`nxp-ico flex-none ${ink ?? "text-[#8fb6ff]"}`} />}
69	          <h3 className="text-[13px] font-extrabold tracking-[-0.01em] text-tx">{title}</h3>
70	          {action && <span className="ml-auto flex-none">{action}</span>}
71	        </div>
72	      )}
73	      <div className={"relative z-[1] min-w-0 flex-1 overflow-auto " + (pad ? "p-3.5" : "")}>{children}</div>
74	    </section>
75	  );
76	}
77	
78	/* ── status ───────────────────────────────────────────────────────────── */
79	
80	export type Tone = "ok" | "warn" | "bad" | "busy" | "idle";
81	
82	const TONE: Record<Tone, { dot: string; ink: string; ring: string }> = {
83	  ok:   { dot: "bg-emerald-400", ink: "text-emerald-300", ring: "border-emerald-400/40 bg-emerald-500/12" },
84	  warn: { dot: "bg-amber-400",   ink: "text-amber-300",   ring: "border-amber-400/40 bg-amber-500/12" },
85	  bad:  { dot: "bg-rose-400",    ink: "text-rose-300",    ring: "border-rose-400/40 bg-rose-500/12" },
86	  busy: { dot: "bg-sky-400",     ink: "text-sky-300",     ring: "border-sky-400/40 bg-sky-500/12" },
87	  idle: { dot: "bg-slate-400",   ink: "text-slate-300",   ring: "border-slate-400/30 bg-slate-500/12" },
88	};
89	
90	export function StatusPill({ tone, label, live }: { tone: Tone; label: string; live?: boolean }) {
91	  const t = TONE[tone];
92	  return (
93	    <span className={`inline-flex items-center gap-2 rounded-full border px-2.5 py-1 text-[11.5px] font-bold ${t.ring} ${t.ink}`}>
94	      <span className={`relative h-1.5 w-1.5 flex-none rounded-full ${t.dot} ${live ? "nxp-live" : ""}`} />
95	      {label}
96	    </span>
97	  );
98	}
99	
100	export function Tag({ children, tone = "idle" }: { children: ReactNode; tone?: Tone }) {
101	  const t = TONE[tone];
102	  return (
103	    <span className={`rounded-[6px] border px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide ${t.ring} ${t.ink}`}>
104	      {children}
105	    </span>
106	  );
107	}
108	
109	/* ── figures ──────────────────────────────────────────────────────────── */
110	
111	/** A measured figure. `value === null` means unmeasured — em dash plus reason,
112	 *  never a zero and never an empty bar. */
113	export function Metric({ icon, ink, label, value, sub, pct, tone, unknown, compact }: {
114	  icon: string; ink: string; label: string;
115	  value: string | null; sub?: string; pct?: number; tone?: string;
116	  unknown?: string; compact?: boolean;
117	}) {
118	  const known = value !== null;
119	  return (
120	    <div className={"flex items-start gap-3 " + (compact ? "" : "card card-glass px-4 py-3.5")}>
121	      <Icon name={icon} size={18} tone="inherit" className={`nxp-ico flex-none ${ink}`} />
122	      <span className="flex min-w-0 flex-1 flex-col">
123	        <span className="text-[10px] font-bold uppercase tracking-[0.14em] text-tx-faint">{label}</span>
124	        <span className={"num mt-0.5 truncate text-[18px] font-bold leading-none " + (known ? "text-tx" : "text-tx-dim")}>
125	          {known ? value : "—"}
126	        </span>
127	        {known && pct !== undefined && (
128	          <span className="mt-2 h-[4px] w-full overflow-hidden rounded-full bg-white/10">
129	            <span
130	              className="block h-full rounded-full transition-[width] duration-700 ease-out"
131	              style={{ width: `${Math.min(100, Math.max(0, pct))}%`, background: tone ?? "linear-gradient(90deg,#34d399,#5fd0ff)" }}
132	            />
133	          </span>
134	        )}
135	        {(known ? sub : unknown) && (
136	          <span className="mt-1 truncate text-[11px] text-tx-faint">{known ? sub : unknown}</span>
137	        )}
138	      </span>
139	    </div>
140	  );
141	}
142	
143	/* ── controls ─────────────────────────────────────────────────────────── */
144	
145	/** Segmented control with a sliding thumb. */
146	export function Segmented<T extends string>({ value, onChange, items, size = "md" }: {
147	  value: T; onChange: (v: T) => void;
148	  items: { key: T; label: string; icon?: string }[];
149	  size?: "sm" | "md";
150	}) {
151	  const i = Math.max(0, items.findIndex((x) => x.key === value));
152	  return (
153	    <div className="nxp-seg" style={{ ["--n" as string]: items.length, ["--i" as string]: i }}>
154	      {items.map((it) => {
155	        const on = it.key === value;
156	        return (
157	          <button
158	            key={it.key}
159	            type="button"
160	            onClick={() => onChange(it.key)}
161	            className={
162	              "inline-flex items-center justify-center gap-1.5 whitespace-nowrap rounded-[9px] font-semibold transition-colors " +
163	              (size === "sm" ? "px-2.5 py-1 text-[11.5px] " : "px-3.5 py-1.5 text-[12.5px] ") +
164	              (on ? "text-[#fff]" : "text-tx-dim hover:text-tx")
165	            }
166	          >
167	            {it.icon && <Icon name={it.icon} size={13} tone="inherit" className={on ? "text-[#fff]" : "text-[#7f9ad0]"} />}
168	            {it.label}
169	          </button>
170	        );
171	      })}
172	    </div>
173	  );
174	}
175	
176	export function CopyChip({ label, value, mono = true }: { label: string; value: string; mono?: boolean }) {
177	  const [done, setDone] = useState(false);
178	  return (
179	    <button
180	      type="button"
181	      title={`Copy ${label}`}
182	      onClick={async () => {
183	        try {
184	          await navigator.clipboard.writeText(value);
185	          setDone(true);
186	          setTimeout(() => setDone(false), 1300);
187	        } catch {
188	          /* Insecure origin or denied. The text is selectable; nothing to say. */
189	        }
190	      }}
191	      className="group inline-flex max-w-full items-center gap-2 rounded-[9px] border border-rim-soft bg-well py-1.5 pl-2.5 pr-2 transition hover:border-[#8b5cff]/45 hover:bg-hover"
192	    >
193	      <span className="text-[9.5px] font-bold uppercase tracking-[0.13em] text-tx-faint">{label}</span>
194	      <span className={"truncate text-[12px] text-tx-body " + (mono ? "mono" : "")}>{value}</span>
195	      <Icon
196	        name={done ? "checkcircle" : "copy"}
197	        size={12}
198	        tone="inherit"
199	        className={done ? "text-emerald-300" : "text-tx-faint group-hover:text-tx"}
200	      />
201	    </button>
202	  );
203	}
204	
205	/** A dropdown anchored to its trigger. Portalled to the body: a backdrop-filter
206	 *  ancestor would otherwise become the containing block for a fixed child. */
207	export function Menu({ label, icon = "ellipsis", items }: {
208	  label?: string;
209	  icon?: string;
210	  items: { key: string; label: string; icon?: string; danger?: boolean; onSelect: () => void }[];
211	}) {
212	  const [open, setOpen] = useState(false);
213	  const [rect, setRect] = useState<{ top: number; right: number } | null>(null);
214	  const btn = useRef<HTMLButtonElement | null>(null);
215	
216	  useEffect(() => {
217	    if (!open) return;
218	    const close = () => setOpen(false);
219	    window.addEventListener("scroll", close, true);
220	    window.addEventListener("resize", close);
221	    const esc = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
222	    window.addEventListener("keydown", esc);
223	    return () => {
224	      window.removeEventListener("scroll", close, true);
225	      window.removeEventListener("resize", close);
226	      window.removeEventListener("keydown", esc);
227	    };
228	  }, [open]);
229	
230	  return (
231	    <>
232	      <button
233	        ref={btn}
234	        type="button"
235	        onClick={() => {
236	          const r = btn.current?.getBoundingClientRect();
237	          if (r) setRect({ top: r.bottom + 8, right: window.innerWidth - r.right });
238	          setOpen((v) => !v);
239	        }}
240	        className="inline-flex items-center gap-1.5 rounded-[10px] border border-rim-hi bg-[color-mix(in_srgb,var(--fg)_4%,transparent)] px-3 py-2 text-[12.5px] font-semibold text-tx-body transition hover:border-[#8b5cff]/45 hover:text-tx"
241	      >
242	        {label}
243	        <Icon name={icon} size={14} tone="inherit" />
244	      </button>
245	      {open && rect &&
246	        createPortal(
247	          <>
248	            <div className="fixed inset-0 z-[80]" onClick={() => setOpen(false)} />
249	            <div
250	              className="card card-glass nxp-modal fixed z-[81] min-w-[212px] overflow-hidden p-1"
251	              style={{ top: rect.top, right: rect.right }}
252	            >
253	              {items.map((it) => (
254	                <button
255	                  key={it.key}
256	                  type="button"
257	                  onClick={() => { setOpen(false); it.onSelect(); }}
258	                  className={
259	                    "flex w-full items-center gap-2.5 rounded-[9px] px-3 py-2 text-left text-[12.5px] font-semibold transition " +
260	                    (it.danger
261	                      ? "text-rose-300 hover:bg-rose-500/12"
262	                      : "text-tx-body hover:bg-[color-mix(in_srgb,var(--fg)_6%,transparent)] hover:text-tx")
263	                  }
264	                >
265	                  {it.icon && <Icon name={it.icon} size={14} tone="inherit" className="flex-none" />}
266	                  {it.label}
267	                </button>
268	              ))}
269	            </div>
270	          </>,
271	          document.body,
272	        )}
273	    </>
274	  );
275	}
276	
277	/** Confirmation for anything destructive. Optional `typeToConfirm` makes the
278	 *  customer type the server's name — used for delete, not for reboot. */
279	export function Confirm({ open, title, body, confirmLabel, danger, typeToConfirm, onConfirm, onClose }: {
280	  open: boolean;
281	  title: string;
282	  body: ReactNode;
283	  confirmLabel: string;
284	  danger?: boolean;
285	  typeToConfirm?: string;
286	  onConfirm: () => void;
287	  onClose: () => void;
288	}) {
289	  const [typed, setTyped] = useState("");
290	  useEffect(() => { if (open) setTyped(""); }, [open]);
291	  if (!open) return null;
292	  const ready = !typeToConfirm || typed.trim() === typeToConfirm;
293	
294	  return createPortal(
295	    <div className="fixed inset-0 z-[90] grid place-items-center p-4">
296	      <div className="nxp-backdrop absolute inset-0 bg-black/70" onClick={onClose} />
297	      <div className="card card-glass nxp-modal relative z-[91] w-full max-w-[460px] p-5">
298	        <div className="flex items-start gap-3">
299	          <span className={`grid h-[38px] w-[38px] flex-none place-items-center rounded-[11px] border ${danger ? "border-rose-400/35 bg-rose-950/40" : "border-sky-400/35 bg-sky-950/40"}`}>
300	            <Icon name={danger ? "warntriangle" : "warncircle"} size={18} tone="inherit" className={danger ? "text-rose-300" : "text-sky-300"} />
301	          </span>
302	          <div className="min-w-0 flex-1">
303	            <h3 className="text-[15px] font-extrabold text-tx">{title}</h3>
304	            <div className="mt-1.5 text-[12.5px] leading-relaxed text-tx-dim">{body}</div>
305	          </div>
306	        </div>
307	
308	        {typeToConfirm && (
309	          <label className="mt-4 block">
310	            <span className="text-[11.5px] text-tx-faint">
311	              Type <span className="mono text-tx">{typeToConfirm}</span> to confirm
312	            </span>
313	            <input
314	              value={typed}
315	              onChange={(e) => setTyped(e.target.value)}
316	              autoFocus
317	              spellCheck={false}
318	              className="input mono mt-1.5 w-full"
319	            />
320	          </label>
321	        )}
322	
323	        <div className="mt-5 flex justify-end gap-2">
324	          <button
325	            type="button"
326	            onClick={onClose}
327	            className="rounded-[10px] border border-rim-hi px-3.5 py-2 text-[12.5px] font-semibold text-tx-dim transition hover:text-tx"
328	          >
329	            Cancel
330	          </button>
331	          <button
332	            type="button"
333	            disabled={!ready}
334	            onClick={() => { onConfirm(); onClose(); }}
335	            className={
336	              "rounded-[10px] px-4 py-2 text-[12.5px] font-bold transition " +
337	              (danger
338	                ? "bg-rose-500/90 text-[#fff] hover:bg-rose-500 disabled:opacity-40"
339	                : "nx-cta disabled:opacity-40")
340	            }
341	          >
342	            {confirmLabel}
343	          </button>
344	        </div>
345	      </div>
346	    </div>,
347	    document.body,
348	  );
349	}
350	
351	export function Skeleton({ className = "" }: { className?: string }) {
352	  return <span className={"nxp-skel block " + className} />;
353	}
