38	export function VpsPlanSlider({
39	  serverId, currentPlanId, currentDiskGB, currentPriceCents,
40	  expiresAt, termMonths, termPromoPercent, annualDiscountPct,
41	  isFree, walletBalanceCents, plans, disabled,
