201	
202	        <div className="mt-4 flex flex-wrap items-center justify-between gap-3 border-t border-rim-soft pt-3.5">
203	          <div className="min-w-0">
204	            {isCurrent ? (
205	              <p className="text-[12.5px] text-tx-faint">This is the plan you are on.</p>
206	            ) : tooSmall(target) ? (
207	              <p className="text-[12.5px] text-amber-300">
