5	
6	/**
7	 * The VPS panel's shared furniture.
8	 *
9	 * These are the game panel's `Tile` and `Card` verbatim in shape and sizing,
10	 * not a second interpretation of them. The first pass at this panel invented
11	 * its own full-width `<section>` with a padded header and no icon plate, which
12	 * is why its cards read as oversized slabs stacked down the page while the game
13	 * panel's read as a bento. If the game panel's tile changes, change it here to
14	 * match — two products that look like one product is the whole point.
15	 */
16	
17	/** A titled panel with a ruled header, so a column of them reads as a stack of
18	 *  cards rather than one long scroll of prose. */
19	export function Card({ title, action, children, className = "" }: {
20	  title: string;
21	  action?: ReactNode;
22	  children: ReactNode;
23	  className?: string;
24	}) {
25	  return (
26	    <section className={"card card-glass flex min-w-0 flex-col " + className}>
27	      <div className="flex items-center gap-3 border-b border-rim-soft px-4 py-3">
28	        <h3 className="text-[14px] font-extrabold text-tx">{title}</h3>
29	        {action && <span className="ml-auto flex-none">{action}</span>}
30	      </div>
31	      <div className="min-w-0 flex-1 p-4">{children}</div>
32	    </section>
33	  );
34	}
35	
36	/** A row inside a card's body — used for forwards, rules, events, jobs. */
37	export function Row({ children, dim }: { children: ReactNode; dim?: boolean }) {
38	  return (
39	    <li className={"flex flex-wrap items-center gap-x-3 gap-y-2 border-t border-rim-soft py-2.5 first:border-t-0 " + (dim ? "opacity-55" : "")}>
40	      {children}
41	    </li>
42	  );
43	}
44	
45	export const TAG = "rounded-[6px] border px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide";
46	
47	/** Short explanatory copy above a card's controls. Kept to one narrow measure —
48	 *  a paragraph that runs the full width of a 1600px panel is unreadable. */
49	export function Hint({ children }: { children: ReactNode }) {
50	  return <p className="mb-3 max-w-[72ch] text-[12px] leading-relaxed text-tx-faint">{children}</p>;
51	}
52	
53	/* ── the side sub-navigation ──────────────────────────────────────────────
54	   Lifted from GameSettingsShell, which is the arrangement the owner asked for
55	   on every tab that has sub-sections: a 252px rail of named sections with a
56	   one-line description each, and the section's own cards to the right.
57	
58	   Generic on the key so Settings, Networking and Backups can all use it
59	   without three near-identical copies. */
60	
61	export type SubSection<K extends string> = {
62	  key: K;
63	  label: string;
64	  sub: string;
65	  icon: string;
66	  tone?: "danger";
67	};
68	
69	export function SubNav<K extends string>({ sections, slots, initial }: {
70	  sections: SubSection<K>[];
71	  slots: Partial<Record<K, ReactNode>>;
72	  initial?: K;
73	}) {
74	  const shown = sections.filter((s) => slots[s.key]);
75	  const [sec, setSec] = useState<K | undefined>(initial ?? shown[0]?.key);
76	  const active = shown.find((s) => s.key === sec) ?? shown[0];
77	
78	  if (!active) return null;
79	
80	  return (
81	    <div className="grid gap-4 lg:grid-cols-[252px_minmax(0,1fr)]">
82	      <nav className="flex h-fit flex-col gap-1 rounded-[16px] border border-rim-hi bg-surface p-2">
83	        {shown.map((s) => {
84	          const on = active.key === s.key;
85	          const danger = s.tone === "danger";
86	          return (
87	            <button
88	              key={s.key}
89	              type="button"
90	              onClick={() => setSec(s.key)}
91	              aria-current={on ? "true" : undefined}
92	              className={
93	                "flex items-center gap-3 rounded-[11px] border px-3 py-2.5 text-left transition " +
94	                (on
95	                  ? danger
96	                    ? "border-red-500/45 bg-red-500/12"
97	                    : "border-[#8b5cff]/70 bg-[linear-gradient(120deg,rgba(80,40,190,.42),rgba(30,40,120,.3))]"
98	                  : "border-transparent hover:bg-[color-mix(in_srgb,var(--fg)_4%,transparent)]")
99	              }
100	            >
101	              <Icon
102	                name={s.icon}
103	                size={16}
104	                tone="inherit"
105	                className={"flex-none " + (danger ? "text-red-400" : on ? "text-[#fff]" : "text-[#7f9ad0]")}
106	              />
107	              <span className="flex min-w-0 flex-col">
108	                <span className={"truncate text-[13px] font-bold " + (danger ? "text-red-300" : on ? "text-[#fff]" : "text-tx-dim")}>
109	                  {s.label}
110	                </span>
111	                <span className="truncate text-[11px] text-tx-faint">{s.sub}</span>
112	              </span>
113	            </button>
114	          );
115	        })}
116	      </nav>
117	
118	      <div className="flex min-w-0 flex-col gap-4 [&_.card]:rounded-[16px]">{slots[active.key]}</div>
119	    </div>
120	  );
121	}
