"use client";

import { useMemo } from "react";
import { Icon } from "@/components/nx/Icon";
import { fmtMoney } from "@/components/ui/primitives";
import { Panel } from "./kit";

/**
 * The plan chart.
 *
 * WHAT REPLACED THE SLIDER, AND WHY. This used to be a drag track whose stops
 * were the plans (VpsPlanSlider). The track ran the full catalogue in both
 * directions, which was wrong twice over: a downgrade is not self-service on
 * this platform, and the stops below the current plan LOOKED pickable — they
 * only dimmed when the target's disk was too small. So a customer could drag
 * down, read a price, press Apply and be told to ask support. A chart says the
 * same thing without the dead end: every plan is drawn, the ones you cannot
 * move to are visibly locked, and only the ones above you can be pressed.
 *
 * This component is CONTROLLED and owns no money. The prorated charge, the
 * renewal projection and the checkout all live in VpsResourcesPanel, which
 * computes them once through the same functions the server charges through.
 */

export type ResourcePlanRow = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
};

export function VpsPlanChart({
  plans, currentPlanId, currentDiskGB, selectedPlanId, onSelect, disabled,
}: {
  plans: ResourcePlanRow[];
  currentPlanId: string;
  /** The plan disk in force today — a target can never have LESS. */
  currentDiskGB: number;
  /** null = "stay on the current plan". */
  selectedPlanId: string | null;
  onSelect: (planId: string | null) => void;
  disabled?: boolean;
}) {
  /* Ordered by price, which is also the order of capability. */
  const ordered = useMemo(() => [...plans].sort((a, b) => a.priceCents - b.priceCents), [plans]);
  const currentIdx = Math.max(0, ordered.findIndex((p) => p.id === currentPlanId));
  const current = ordered[currentIdx];
  const maxPrice = Math.max(1, ...ordered.map((p) => p.priceCents));

  /* Two independent reasons a plan cannot be a target, both drawn the same way
     and both explained on hover:
       - it is the plan you are on, or below it (downgrades are not self-service)
       - its disk is smaller than the disk you already have (disks only grow) */
  const lockReason = (p: ResourcePlanRow, i: number): string | null => {
    if (i === currentIdx) return "This is the plan you are on.";
    if (i < currentIdx || p.priceCents <= current.priceCents) {
      return "Moving down refunds the difference, which we handle by hand — ask support.";
    }
    if (p.diskGB < currentDiskGB) {
      return `Disks only ever grow, and this plan has ${p.diskGB} GB.`;
    }
    return null;
  };

  const upgradable = ordered.filter((p, i) => lockReason(p, i) === null);
  const atTop = upgradable.length === 0;
  const selected = selectedPlanId ? ordered.find((p) => p.id === selectedPlanId) ?? null : null;

  return (
    <Panel
      title="Plan"
      icon="cpu"
      accent="#8b5cff"
      ink="text-[#b08bff]"
      action={
        selected ? (
          <button
            type="button"
            onClick={() => onSelect(null)}
            className="rounded-[8px] border border-rim-hi px-2.5 py-1 text-[11px] font-bold text-tx-dim transition hover:text-tx"
          >
            Clear
          </button>
        ) : (
          <span className="text-[11px] text-tx-faint">
            {atTop ? "Largest plan" : `${upgradable.length} upgrade${upgradable.length === 1 ? "" : "s"} available`}
          </span>
        )
      }
    >
      <p className="mb-3.5 max-w-[76ch] text-[12px] leading-relaxed text-tx-faint">
        CPU and memory move together — a plan is a bundle and a resize targets a plan, so there is one
        chart rather than four sliders that could not be honoured. Storage is genuinely separate and has
        its own control below.
      </p>

      {/* ── the chart ──────────────────────────────────────────────────────
          Bar height is the plan's price against the largest plan's, so the
          step you are about to take has a visible size. */}
      <div className="flex items-stretch gap-1.5 sm:gap-2">
        {ordered.map((p, i) => {
          const locked = lockReason(p, i);
          const isCurrent = i === currentIdx;
          const on = selectedPlanId === p.id;
          const h = 22 + (p.priceCents / maxPrice) * 78;
          return (
            <button
              key={p.id}
              type="button"
              disabled={!!locked || disabled}
              title={locked ?? `Upgrade to ${p.name}`}
              aria-pressed={on}
              onClick={() => onSelect(on ? null : p.id)}
              className={
                "group flex min-w-0 flex-1 flex-col items-center gap-2 rounded-[13px] border p-2 pt-2.5 text-center transition " +
                (on
                  ? "border-[#8b5cff]/70 bg-[color-mix(in_srgb,var(--color-violet)_16%,transparent)]"
                  : locked
                    ? "cursor-not-allowed border-transparent opacity-45"
                    : "border-rim-soft hover:border-[#8b5cff]/50 hover:bg-[color-mix(in_srgb,var(--fg)_5%,transparent)]")
              }
            >
              <span className="flex h-[104px] w-full items-end justify-center">
                <span
                  className="block w-[58%] min-w-[14px] rounded-t-[7px] transition-[height,background] duration-500 ease-out"
                  style={{
                    height: `${h}%`,
                    background: on
                      ? "linear-gradient(180deg,#a97bff,#3fbcd8)"
                      : locked
                        ? "color-mix(in srgb, var(--fg) 14%, transparent)"
                        : "color-mix(in srgb, var(--color-blue) 42%, transparent)",
                  }}
                />
              </span>

              <span className="flex w-full min-w-0 flex-col items-center gap-0.5">
                <span className={"num text-[12.5px] font-extrabold leading-none " + (on ? "text-tx" : "text-tx-body")}>
                  {p.cpuCores} vCPU
                </span>
                <span className="num text-[10.5px] leading-none text-tx-faint">
                  {Math.round(p.ramMB / 1024)} GB · {p.diskGB} GB
                </span>
                <span className={"num mt-0.5 text-[11.5px] font-bold leading-none " + (on ? "text-[#b08bff]" : "text-tx-dim")}>
                  {fmtMoney(p.priceCents)}
                </span>
                {isCurrent ? (
                  <span className="mt-1 rounded-full border border-emerald-400/40 bg-emerald-500/12 px-1.5 py-[1px] text-[9px] font-bold uppercase tracking-wide text-emerald-300">
                    Now
                  </span>
                ) : locked ? (
                  <Icon name="lock" size={10} tone="inherit" className="mt-1 text-tx-faint" />
                ) : (
                  <span className="mt-1 text-[9px] font-bold uppercase tracking-wide text-tx-faint opacity-0 transition group-hover:opacity-100">
                    {on ? "Picked" : "Pick"}
                  </span>
                )}
              </span>
            </button>
          );
        })}
      </div>

      {/* ── what the pick changes ──────────────────────────────────────── */}
      {selected && (
        <div className="nx-rise mt-3.5 grid gap-3 rounded-[13px] border border-rim-soft bg-well p-3.5 sm:grid-cols-4">
          {([
            ["vCPU", `${selected.cpuCores}`, current.cpuCores === selected.cpuCores ? null : `from ${current.cpuCores}`],
            ["Memory", `${Math.round(selected.ramMB / 1024)} GB`, current.ramMB === selected.ramMB ? null : `from ${Math.round(current.ramMB / 1024)} GB`],
            ["Plan disk", `${selected.diskGB} GB`, current.diskGB === selected.diskGB ? null : `from ${current.diskGB} GB`],
            ["Bandwidth", `${selected.bandwidthTB} TB`, current.bandwidthTB === selected.bandwidthTB ? null : `from ${current.bandwidthTB} TB`],
          ] as [string, string, string | null][]).map(([k, v, was]) => (
            <div key={k} className="flex min-w-0 flex-col gap-0.5">
              <span className="text-[10px] font-bold uppercase tracking-[0.14em] text-tx-faint">{k}</span>
              <span className="num text-[16px] font-bold leading-none text-tx">{v}</span>
              {was && <span className="text-[11px] text-emerald-400">{was}</span>}
            </div>
          ))}
          <p className="flex items-start gap-2 text-[11.5px] leading-relaxed text-tx-faint sm:col-span-4">
            <Icon name="warncircle" size={13} tone="inherit" className="mt-[1px] flex-none text-amber-400" />
            Upgrading power-cycles the server, and a larger plan is permanent — disks only ever grow.
          </p>
        </div>
      )}

      {/* ── already at the top ─────────────────────────────────────────────
          The sidebar's quiet "need something else?" card is not enough here:
          for a customer on the largest plan this control has nothing to offer,
          so the next step has to be the loudest thing in it. */}
      {atTop && (
        <div className="mt-3.5 flex flex-wrap items-center gap-3.5 rounded-[13px] border border-[#8b5cff]/45 bg-[color-mix(in_srgb,var(--color-violet)_10%,transparent)] p-4">
          <span className="grid h-[40px] w-[40px] flex-none place-items-center rounded-[12px] border border-[#8b5cff]/45 bg-[color-mix(in_srgb,var(--color-violet)_16%,transparent)]">
            <Icon name="crown" size={19} tone="inherit" className="text-[#b08bff]" />
          </span>
          <div className="min-w-0 flex-1">
            <p className="text-[13.5px] font-extrabold text-tx">You are on the largest plan we sell.</p>
            <p className="mt-0.5 max-w-[62ch] text-[12px] leading-relaxed text-tx-dim">
              Need more resources? We build custom plans at the same per-vCPU and per-GB rates the
              catalogue is priced from — tell support what you need and we will quote it.
            </p>
          </div>
          <a
            href="/dashboard/support"
            className="nx-cta flex-none px-4 py-2.5 text-[12.5px]"
          >
            Contact support for a custom plan
          </a>
        </div>
      )}
    </Panel>
  );
}

"use client";

import { Icon } from "@/components/nx/Icon";
import { fmtMoney } from "@/components/ui/primitives";
import {
  EXTRA_DISK_ONE_WAY_NOTE,
  EXTRA_DISK_STEP_GB,
  effectiveDiskGB,
  extraDiskCentsAt,
} from "@/lib/extra-disk";
import { Panel } from "./kit";

/**
 * Extra storage, as the deploy wizard's volume meter.
 *
 * This is the SAME control the wizard uses to sell disk on a new order
 * (components/nx/OrderBits.tsx DiskMeter) — the same `/nx/svc/volume.webp`
 * render, the same `.range` track, the same shortcut chips — pointed at the
 * post-deploy product instead. The difference that matters is invisible: a
 * wizard's disk is not billed until the order is paid, while this one is added
 * to a term already running, so it carries a prorated charge. That figure is
 * computed by VpsResourcesPanel through lib/extra-disk.ts's own
 * `extraDiskProrateCents`, the function `diskExpandQuote` charges through, and
 * passed in here — it is not re-derived beside the slider.
 *
 * GROWTH IS ONE-WAY, and lib/extra-disk.ts requires every surface that sells
 * disk to say so before taking money. EXTRA_DISK_ONE_WAY_NOTE is rendered
 * verbatim below, and again in the checkout sheet.
 */
export function VpsStorageMeter({
  planDiskGB, extraDiskGB, perGbCents, maxAddGB, addGB, onChange, prorateCents, disabled,
}: {
  /** The plan's own disk allowance (game-aware base, not `plan.diskGB` raw). */
  planDiskGB: number;
  /** Extra disk already bought for this server. */
  extraDiskGB: number;
  perGbCents: number;
  /** From maxAddableExtraDiskGB — 0 means the server is at the ceiling. */
  maxAddGB: number;
  addGB: number;
  onChange: (gb: number) => void;
  /** Prorated charge for `addGB` over the rest of the term, computed upstream. */
  prorateCents: number;
  disabled?: boolean;
}) {
  const currentTotal = effectiveDiskGB(planDiskGB, extraDiskGB);
  const newTotal = currentTotal + addGB;
  const monthlyCents = extraDiskCentsAt(addGB, perGbCents);
  const pct = maxAddGB > 0 ? (addGB / maxAddGB) * 100 : 0;

  return (
    <Panel
      title="Storage"
      icon="database"
      accent="#3fbcd8"
      ink="text-[#5fd0ff]"
      action={<span className="num text-[11px] text-tx-faint">{fmtMoney(perGbCents)}/GB per month</span>}
    >
      {maxAddGB <= 0 ? (
        <div className="flex items-start gap-3">
          <img
            src="/nx/svc/volume.webp"
            alt=""
            aria-hidden
            draggable={false}
            className="h-[42px] w-[42px] flex-none object-contain opacity-50"
          />
          <p className="text-[12.5px] leading-relaxed text-tx-dim">
            This server is at the maximum root-disk size ({currentTotal} GB). For more space, attach a
            block-storage volume — those stay portable and can be detached later.
          </p>
        </div>
      ) : (
        <>
          <div className="flex flex-wrap items-center gap-3">
            <img
              src="/nx/svc/volume.webp"
              alt=""
              aria-hidden
              draggable={false}
              className="h-[52px] w-[52px] flex-none object-contain"
            />
            <span className="flex min-w-0 flex-1 flex-col gap-0.5">
              <span className="text-[13.5px] font-extrabold text-tx">Extra storage</span>
              <span className="text-[11.3px] text-tx-faint">
                {currentTotal} GB today
                {extraDiskGB > 0 && ` (${planDiskGB} GB plan + ${extraDiskGB} GB added)`} · grows live, no
                reboot
              </span>
            </span>
            <span className="flex-none text-right">
              <span key={addGB} className="num nx-pop block text-[17px] font-extrabold leading-none text-tx">
                {addGB === 0 ? "None" : `+${addGB} GB`}
              </span>
              <span className="num mt-1 block text-[11px] text-tx-faint">
                {addGB === 0 ? "included only" : `${fmtMoney(monthlyCents)}/mo`}
              </span>
            </span>
          </div>

          <div className="mt-4 flex flex-wrap items-center gap-3">
            <input
              type="range"
              aria-label="Extra storage to add, in GB"
              min={0}
              max={maxAddGB}
              step={EXTRA_DISK_STEP_GB}
              value={addGB}
              disabled={disabled}
              onChange={(e) => onChange(Number(e.target.value))}
              className="range min-w-[180px] flex-1 disabled:cursor-not-allowed disabled:opacity-50"
              style={{ "--pct": `${pct}%` } as React.CSSProperties}
            />
            <div className="flex flex-none gap-1.5">
              {[0, 50, 100, 250].filter((v) => v === 0 || v <= maxAddGB).map((v) => (
                <button
                  key={v}
                  type="button"
                  disabled={disabled}
                  onClick={() => onChange(v)}
                  className={
                    "rounded-full px-2.5 py-1 text-[11px] font-bold transition-colors " +
                    (addGB === v
                      ? "bg-[linear-gradient(100deg,#1a55cf,#6f2ee0)] text-[#fff]"
                      : "border border-rim-hi text-tx-dim hover:text-tx")
                  }
                >
                  {v === 0 ? "None" : `${v}G`}
                </button>
              ))}
            </div>
          </div>

          <p className="mt-2 text-[11px] text-tx-faint">
            Up to {maxAddGB} GB in one go, in {EXTRA_DISK_STEP_GB} GB steps.
          </p>

          {addGB > 0 && (
            <div className="nx-rise mt-3.5 flex flex-wrap items-center justify-between gap-3 rounded-[13px] border border-rim-soft bg-well px-3.5 py-3">
              <span className="text-[12.5px] text-tx-dim">
                Disk grows to <span className="num font-bold text-tx">{newTotal} GB</span> and adds{" "}
                <span className="num font-bold text-tx">{fmtMoney(monthlyCents)}/mo</span> to every renewal.
              </span>
              <span className="text-[12.5px] text-tx-dim">
                {prorateCents > 0 ? (
                  <>
                    Due now <span className="num font-bold text-tx">{fmtMoney(prorateCents)}</span> for the
                    rest of your term
                  </>
                ) : (
                  "Nothing due now."
                )}
              </span>
            </div>
          )}

          <p className="mt-3 flex items-start gap-2 rounded-[11px] border border-amber-500/25 bg-amber-500/10 px-3 py-2.5 text-[11.5px] leading-relaxed text-amber-300">
            <Icon name="warncircle" size={13} tone="inherit" className="mt-[1px] flex-none" />
            {EXTRA_DISK_ONE_WAY_NOTE}
          </p>
        </>
      )}
    </Panel>
  );
}

