@import "tailwindcss";

/* the animatable angle behind the liquid-glass card's travelling rim —
   @property has to be declared at the top level or Tailwind drops it */
@property --orbit { syntax: "<angle>"; initial-value: 0deg; inherits: false; }
@keyframes lgc-orbit { to { --orbit: 360deg; } }

@theme {
  /* Brand typeface (Plus Jakarta Sans / JetBrains Mono), injected as CSS vars by
     next/font in app/layout.tsx.
     Mapping them here makes Tailwind's `font-sans` / `font-mono` utilities — and the
     body default below — resolve to Geist, with a graceful system fallback. */
  --font-sans: var(--font-nx-sans), ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-mono: var(--font-nx-mono), ui-monospace, "SFMono-Regular", "Menlo", monospace;

  /* ═══════════════════════════════════════════════════════════════════════
     NEXION palette, mapped onto the existing token slots.

     The slot NAMES are kept (brand-*, navy-*, accent-*, slate-*) so all ~4,700
     existing utility usages keep resolving — but every VALUE is the Nexion one.
     Nothing of the previous look survives; the names are just sockets.

     Ground rules carried over from the design canvas:
       - the page ground is DARKER than the cards (navy-950 < navy-900)
       - rims are zero-red blues; a periwinkle rim reads cheap at this saturation
       - accents sit deliberately off full saturation (pulled 14-24 points)
     ═══════════════════════════════════════════════════════════════════════ */

  /* brand ramp — Nexion violet #8c3ae9 at the 500 stop */
  --color-brand-50: #f4ecfe;
...

  --animate-fade-up: fade-up 0.4s ease-out both;
  --animate-pulse-dot: pulse-dot 2s ease-in-out infinite;

  /* Admin attention indicators (components/admin/AdminIndicators.tsx). `bell-shake`
     runs once whenever a new ticket / live-chat reply / email arrives; opt-in via
     `motion-safe:` at the call site so reduced-motion users just see the badge. */
  --animate-bell-shake: bell-shake 0.9s cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
  @keyframes bell-shake {
    0%, 100% { transform: rotate(0); }
    10%, 50%, 90% { transform: rotate(-11deg); }
    30%, 70% { transform: rotate(11deg); }
  }

  /* Pricing explorer interactions. `price-pop` runs on every billing-cycle change
     (re-keyed number), `panel-in` on every product-tab switch. Both are opt-in via
     `motion-safe:` at the call site, so reduced-motion users see the resting frame. */
  --animate-price-pop: price-pop 0.42s cubic-bezier(0.22, 1, 0.36, 1) both;
  --animate-panel-in: panel-in 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
  /* Reverse of panel-in — used when <ChatWidget/>'s panel closes, so it settles
     away instead of just vanishing. Shorter and eased the opposite direction
     (ease-in, ends abruptly) since a close should feel snappier than an open. */
  --animate-panel-out: panel-out 0.22s cubic-bezier(0.4, 0, 1, 1) both;

  @keyframes price-pop {
    from { opacity: 0; transform: translateY(7px); filter: blur(3px); }
    to { opacity: 1; transform: translateY(0); filter: blur(0); }
  }
  @keyframes panel-in {
    from { opacity: 0; transform: translateY(12px) scale(0.994); }
    to { opacity: 1; transform: translateY(0) scale(1); }
  }
  @keyframes panel-out {
    from { opacity: 1; transform: translateY(0) scale(1); }
    to { opacity: 0; transform: translateY(10px) scale(0.98); }
  }

