"use client";

import { Icon } from "@/components/nx/Icon";
import { fmtMoney } from "@/components/ui/primitives";
import { Panel } from "./kit";

/**
 * Add-ons — and ONLY the add-ons that have a real backend action behind them.
 *
 * There is no generic "VPS add-on catalogue" on this platform. Exactly two
 * things can be bought for a server that already exists:
 *
 *   Dedicated IPv4   lib/actions-dedicated-ip.ts purchaseDedicatedIp
 *                    (wallet + card, via createDedicatedIpCheckout)
 *   Plus backups     lib/actions-backup.ts upgradeServerBackupTier
 *                    (WALLET ONLY — the MVP has no card leg for this one)
 *
 * The three booleans the deploy wizard calls "add-ons" — malware scanner,
 * daily backup, Docker — are written into `Server.addons` by lib/order.ts at
 * order time and there is no action anywhere that changes them afterwards. A
 * button for them here would be a capability this platform does not have, so
 * the card says what the situation is instead of offering one.
 *
 * An add-on the server already holds is greyed and marked, not hidden: "you
 * have this" is information, and a card that silently shrinks as you buy
 * things makes the customer wonder what else it is not showing them.
 */

export type AddonOption = {
  key: string;
  icon: string;
  ink: string;
  title: string;
  blurb: string;
  /** What it adds to every renewal. */
  monthlyCents: number;
  /** Prorated charge for the rest of the term — null when it cannot be quoted. */
  prorateCents: number | null;
  /** Already on this server. Renders greyed, with no control. */
  owned: boolean;
  /** Why it cannot be picked right now (ignored when `owned`). */
  blockedReason?: string | null;
  /** No card leg exists on the backend — the wallet is the only way to pay. */
  walletOnly?: boolean;
};

export function VpsAddonsCard({
  options, selected, onToggle, disabled,
}: {
  options: AddonOption[];
  selected: Record<string, boolean>;
  onToggle: (key: string, on: boolean) => void;
  disabled?: boolean;
}) {
  const available = options.filter((o) => !o.owned && !o.blockedReason).length;

  return (
    <Panel
      title="Add-ons"
      icon="layers"
      accent="#11c88e"
      ink="text-[#3fd6a4]"
      action={
        <span className="text-[11px] text-tx-faint">
          {available === 0 ? "Nothing to add" : `${available} available`}
        </span>
      }
    >
      <ul className="flex flex-col gap-2">
        {options.map((o) => {
          const on = !!selected[o.key];
          const blocked = !o.owned && !!o.blockedReason;
          const pickable = !o.owned && !blocked && !disabled;
          return (
            <li key={o.key}>
              <button
                type="button"
                disabled={!pickable}
                aria-pressed={on}
                onClick={() => onToggle(o.key, !on)}
                className={
                  "flex w-full items-start gap-3 rounded-[13px] border p-3 text-left transition " +
                  (o.owned || blocked
                    ? "cursor-default border-rim-soft bg-well opacity-55"
                    : on
                      ? "border-mint/55 bg-mint/10"
                      : "border-rim-soft hover:border-mint/40 hover:bg-[color-mix(in_srgb,var(--fg)_4%,transparent)]")
                }
              >
                <Icon
                  name={o.icon}
                  size={19}
                  tone="inherit"
                  className={"nxp-ico mt-0.5 flex-none " + (o.owned || blocked ? "text-tx-faint" : o.ink)}
                />

                <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                  <span className="flex flex-wrap items-center gap-2">
                    <span className="text-[13px] font-extrabold text-tx">{o.title}</span>
                    {o.owned && (
                      <span className="rounded-full border border-mint/45 bg-mint/12 px-2 py-[1px] text-[9.5px] font-bold uppercase tracking-wide text-mint">
                        On this server
                      </span>
                    )}
                    {!o.owned && o.walletOnly && (
                      <span className="rounded-full border border-rim-hi px-2 py-[1px] text-[9.5px] font-bold uppercase tracking-wide text-tx-faint">
                        Wallet only
                      </span>
                    )}
                  </span>
                  <span className="text-[11.5px] leading-relaxed text-tx-dim">{o.blurb}</span>
                  {blocked && (
                    <span className="text-[11px] leading-relaxed text-amber">{o.blockedReason}</span>
                  )}
                </span>

                <span className="flex flex-none flex-col items-end gap-1 pl-1">
                  <span className="num text-[12.5px] font-bold text-tx">
                    {fmtMoney(o.monthlyCents)}
                    <span className="text-[10px] font-normal text-tx-faint">/mo</span>
                  </span>
                  {o.owned ? (
                    <Icon name="checkcircle" size={15} tone="inherit" className="text-mint" />
                  ) : blocked ? (
                    <Icon name="lock" size={13} tone="inherit" className="text-tx-faint" />
                  ) : (
                    <span
                      className={
                        "grid h-[19px] w-[19px] place-items-center rounded-[6px] border transition " +
                        (on ? "border-mint/60 bg-mint/25" : "border-rim-hi")
                      }
                    >
                      {on && <Icon name="checkcircle" size={12} tone="inherit" className="text-mint" />}
                    </span>
                  )}
                  {!o.owned && !blocked && o.prorateCents !== null && o.prorateCents > 0 && (
                    <span className="num text-[10.5px] text-tx-faint">{fmtMoney(o.prorateCents)} now</span>
                  )}
                </span>
              </button>
            </li>
          );
        })}
      </ul>

      <p className="mt-3 border-t border-rim-soft pt-3 text-[11px] leading-relaxed text-tx-faint">
        Malware scanning and Docker are chosen when a server is created and are not changeable from here.
        Backup frequency and restore points live on the Backups tab; portable block-storage volumes are
        managed under Volumes.
      </p>
    </Panel>
  );
}

