"use client";

import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import { useRouter } from "next/navigation";
import { Icon } from "@/components/nx/Icon";
import { fmtMoney } from "@/components/ui/primitives";
import { StripeCheckoutModal } from "@/components/customer/StripeCheckoutModal";
import { STRIPE_MIN_CENTS, walletSplit } from "@/lib/wallet-split";

/**
 * The cart, and the payment sheet it opens.
 *
 * ─── WHY THIS IS NOT ONE COMBINED CHARGE ─────────────────────────────────────
 * The deploy wizard's bar summarises ONE purchase and ends in ONE PaymentIntent,
 * because nothing exists yet. Here the three paid changes are three separate,
 * already-audited money paths — `resizeServer`, `expandServerDisk`,
 * `purchaseDedicatedIp` — each with its own Stripe Checkout Session, its own
 * metadata and its own idempotent confirm/webhook fulfilment, plus
 * `upgradeServerBackupTier`, which has no card leg at all. Two facts decided the
 * shape of this component:
 *
 *   1. Every one of the first three QUEUES A JOB, and every one of them refuses
 *      to start while any job is QUEUED or RUNNING on that server ("one in-flight
 *      job per server", the platform's oldest rule). So even behind a single
 *      PaymentIntent the backend physically cannot apply them together.
 *   2. A combined intent would therefore have to take the money for changes it
 *      could not yet apply, and reconcile them later against four different
 *      fulfilment paths. Paying for something we have not done is the one failure
 *      this codebase's money comments exist to prevent.
 *
 * So the cart shows the combined picture — which is real, and computed through
 * the same functions the server charges through — and then applies the changes
 * IN ORDER through the existing actions, one confirmation each. The sheet says
 * that out loud rather than implying a single charge. If combining the charge is
 * ever worth doing, it needs a backend that can hold several pending changes
 * against one payment and drain them as jobs free up; that does not exist today.
 */

export type CartResult = {
  error?: string;
  ok?: boolean;
  checkout?: { clientSecret: string; publishableKey: string };
};

export type CartItem = {
  key: string;
  icon: string;
  label: string;
  /** One line saying exactly what changes. */
  detail: string;
  /** What this adds to every renewal, in cents. */
  monthlyCents: number;
  /** The prorated one-off charge for the rest of the term, in cents. */
  dueCents: number;
  /** No card leg exists for this change on the backend — wallet only. */
  walletOnly?: boolean;
  /** Title for the Stripe sheet when this item opens one. */
  checkoutTitle: string;
  /** Calls the REAL server action for this change. */
  run: (useWallet: boolean) => Promise<CartResult | void>;
};

type Status = "idle" | "running" | "done" | "card" | "error";

/* ── the bar ──────────────────────────────────────────────────────────────
   Portalled to the body on purpose: every card on this page is `.card-glass`,
   and a `backdrop-filter` ancestor becomes the containing block for a `fixed`
   child — the bar would otherwise be pinned to the bottom of whichever card
   rendered it. Geometry matches the deploy wizard's bar exactly (the same
   shell, the same rail widths, the same clearance for the chat bubble and the
   mobile tab bar), so the two read as one control in two places. */
export function VpsUpgradeCart({
  items, walletBalanceCents, renewalBeforeCents, renewalAfterCents, renewalLabel, disabled, disabledReason,
}: {
  items: CartItem[];
  walletBalanceCents: number;
  renewalBeforeCents: number;
  renewalAfterCents: number;
  /** e.g. "12 months" — the term the renewal figures are for. */
  renewalLabel: string;
  disabled?: boolean;
  disabledReason?: string | null;
}) {
  const [mounted, setMounted] = useState(false);
  const [shown, setShown] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => setMounted(true), []);
  useEffect(() => {
    /* One frame of the resting (off-screen) position before the transition, so
       the bar slides rather than appearing already in place. */
    if (!items.length) { setShown(false); return; }
    const id = requestAnimationFrame(() => setShown(true));
    return () => cancelAnimationFrame(id);
  }, [items.length]);

  const dueNow = items.reduce((n, i) => n + i.dueCents, 0);
  const monthlyDelta = items.reduce((n, i) => n + i.monthlyCents, 0);

  if (!mounted) return null;

  return createPortal(
    <>
      <div
        className={
          "fixed inset-x-0 bottom-[68px] z-[70] px-3.5 transition-[transform,opacity] duration-300 ease-out sm:px-5 lg:bottom-4 lg:left-[76px] lg:pl-6 lg:pr-[92px] xl:left-[248px] " +
          (shown ? "translate-y-0 opacity-100" : "pointer-events-none translate-y-[140%] opacity-0")
        }
        aria-hidden={!shown}
      >
        {/* A dark island by design in both themes, like the wizard's bar — the
            class re-themes every token inside it at once so `text-tx` does not
            resolve to near-black ink on a near-black bar in light mode. */}
        <div className="nx-dark-island mx-auto flex max-w-[1340px] flex-wrap items-center gap-3 rounded-[16px] border border-rim-hi bg-[rgba(1,15,34,0.94)] px-3.5 py-3 shadow-[0_8px_30px_-12px_rgba(0,4,14,0.9)] backdrop-blur">
          <span className="grid h-[38px] w-[38px] flex-none place-items-center rounded-[11px] border border-rim-hi bg-[rgba(10,40,96,0.45)]">
            <Icon name="cart" size={17} tone="inherit" className="text-[#9dbdee]" />
          </span>

          <div className="flex min-w-0 flex-1 flex-col leading-[1.35]">
            <span className="truncate text-[12.5px] font-bold text-tx">
              {items.length} change{items.length === 1 ? "" : "s"} ready
            </span>
            <span className="truncate text-[11px] text-tx-faint">
              {items.map((i) => i.label).join(" · ")}
            </span>
          </div>

          <div className="flex flex-none items-center gap-4">
            <span className="hidden flex-col text-right leading-[1.3] sm:flex">
              <span className="text-[10px] font-bold uppercase tracking-[0.1em] text-tx-dim">Due now</span>
              <span key={dueNow} className="num nx-pop text-[16px] font-extrabold text-tx">
                {fmtMoney(dueNow)}
              </span>
            </span>
            <span className="hidden flex-col text-right leading-[1.3] md:flex">
              <span className="text-[10px] font-bold uppercase tracking-[0.1em] text-tx-dim">Renewal</span>
              <span key={renewalAfterCents} className="num nx-pop text-[13px] font-bold text-tx">
                {fmtMoney(renewalAfterCents)}
                <span className="text-[10px] font-normal text-tx-faint"> / {renewalLabel}</span>
              </span>
            </span>
            <button
              type="button"
              disabled={disabled}
              onClick={() => setOpen(true)}
              title={disabled ? disabledReason ?? undefined : undefined}
              className="nx-cta h-[42px] flex-none px-5 text-[13px] disabled:cursor-not-allowed disabled:opacity-45"
            >
              Checkout
            </button>
          </div>
        </div>
      </div>

      {open && (
        <CheckoutSheet
          items={items}
          walletBalanceCents={walletBalanceCents}
          renewalBeforeCents={renewalBeforeCents}
          renewalAfterCents={renewalAfterCents}
          renewalLabel={renewalLabel}
          onClose={() => setOpen(false)}
        />
      )}
    </>,
    document.body,
  );
}

/* ── the payment sheet ───────────────────────────────────────────────────── */

function CheckoutSheet({
  items, walletBalanceCents, renewalBeforeCents, renewalAfterCents, renewalLabel, onClose,
}: {
  items: CartItem[];
  walletBalanceCents: number;
  renewalBeforeCents: number;
  renewalAfterCents: number;
  renewalLabel: string;
  onClose: () => void;
}) {
  const router = useRouter();
  /* "Wallet balance" vs "Credit or debit card" is the `useWallet` flag every one
     of these actions already takes — not a new payment-method system. Picking
     the wallet applies as much of the balance as covers the charge and sends the
     remainder to the card, which is exactly what lib/wallet-split.ts does and
     exactly what the server will charge. */
  const [useWallet, setUseWallet] = useState(walletBalanceCents > 0);
  const [status, setStatus] = useState<Record<string, Status>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [busy, setBusy] = useState(false);
  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string; title: string } | null>(null);

  useEffect(() => {
    const esc = (e: KeyboardEvent) => { if (e.key === "Escape" && !busy && !checkout) onClose(); };
    window.addEventListener("keydown", esc);
    return () => window.removeEventListener("keydown", esc);
  }, [busy, checkout, onClose]);

  /* Per-item split against a RUNNING balance, because the items are charged one
     after another and each one spends part of the wallet. Summing one split of
     the combined total would show a number nobody is ever charged. */
  let running = walletBalanceCents;
  const lines = items.map((it) => {
    if (it.walletOnly) {
      const affordable = running >= it.dueCents;
      const applied = Math.min(running, it.dueCents);
      running -= applied;
      return {
        it,
        walletApplied: it.dueCents,
        cardCents: 0,
        shortfall: affordable ? 0 : it.dueCents - applied,
        note: null as string | null,
      };
    }
    const s = walletSplit({ dueCents: it.dueCents, balanceCents: running, useWallet });
    running = Math.max(0, running - s.walletApplied);
    return {
      it,
      walletApplied: s.walletApplied,
      cardCents: s.cardCents,
      shortfall: s.belowStripeMin ? Math.max(0, s.walletApplied - walletBalanceCents) : 0,
      note: s.belowStripeMin
        ? `Under the ${fmtMoney(STRIPE_MIN_CENTS)} card minimum, so this one can only come from your wallet.`
        : s.clampedForStripeMin
          ? `Card payments have a ${fmtMoney(STRIPE_MIN_CENTS)} minimum, so ${fmtMoney(s.cardCents)} goes on the card.`
          : null,
    };
  });

  const dueNow = items.reduce((n, i) => n + i.dueCents, 0);
  const fromWallet = lines.reduce((n, l) => n + l.walletApplied, 0);
  const onCard = lines.reduce((n, l) => n + l.cardCents, 0);
  const shortfall = lines.reduce((n, l) => n + l.shortfall, 0);
  const allDone = items.every((i) => status[i.key] === "done");

  async function pay() {
    setBusy(true);
    for (const it of items) {
      if (status[it.key] === "done") continue;
      setStatus((s) => ({ ...s, [it.key]: "running" }));
      const res = (await it.run(useWallet)) ?? {};
      if (res.checkout) {
        setStatus((s) => ({ ...s, [it.key]: "card" }));
        setCheckout({ ...res.checkout, title: it.checkoutTitle });
        setBusy(false);
        return;
      }
      if (res.error) {
        setStatus((s) => ({ ...s, [it.key]: "error" }));
        setErrors((e) => ({ ...e, [it.key]: res.error! }));
        setBusy(false);
        return;
      }
      setStatus((s) => ({ ...s, [it.key]: "done" }));
    }
    setBusy(false);
    router.refresh();
  }

  return (
    <div className="fixed inset-0 z-[95] grid place-items-center p-4">
      <div className="nxp-backdrop absolute inset-0 bg-black/70" onClick={() => !busy && !checkout && onClose()} />

      <div className="card card-glass nxp-modal relative z-[96] flex max-h-[88vh] w-full max-w-[540px] flex-col overflow-hidden p-0" style={{ ["--tone" as string]: "#8b5cff" }}>
        <div className="relative z-[1] flex flex-none items-center gap-2.5 border-b border-rim-soft px-4 py-3">
          <Icon name="cart" size={16} tone="inherit" className="nxp-ico flex-none text-[#b08bff]" />
          <h3 className="text-[14px] font-extrabold text-tx">Checkout</h3>
          <button
            type="button"
            onClick={() => !busy && !checkout && onClose()}
            aria-label="Close"
            className="ml-auto rounded-[8px] px-2 py-1 text-tx-faint transition hover:text-tx"
          >
            <Icon name="xcircle" size={15} tone="inherit" />
          </button>
        </div>

        <div className="relative z-[1] min-h-0 flex-1 overflow-auto p-4">
          {/* ── what is being bought ─────────────────────────────────────── */}
          <ul className="flex flex-col gap-2">
            {lines.map(({ it, walletApplied, cardCents, note }) => {
              const st = status[it.key] ?? "idle";
              return (
                <li
                  key={it.key}
                  className={
                    "flex items-start gap-3 rounded-[12px] border p-3 transition " +
                    (st === "done"
                      ? "border-mint/45 bg-mint/10"
                      : st === "error"
                        ? "border-rose/45 bg-rose/10"
                        : "border-rim-soft bg-well")
                  }
                >
                  <Icon
                    name={st === "done" ? "checkcircle" : st === "error" ? "warntriangle" : it.icon}
                    size={17}
                    tone="inherit"
                    className={
                      "mt-0.5 flex-none " +
                      (st === "done" ? "text-mint" : st === "error" ? "text-rose" : "text-[#8fb6ff]")
                    }
                  />
                  <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                    <span className="text-[12.5px] font-bold text-tx">{it.label}</span>
                    <span className="text-[11.5px] leading-relaxed text-tx-dim">{it.detail}</span>
                    {errors[it.key] && (
                      <span className="text-[11.5px] leading-relaxed text-rose">{errors[it.key]}</span>
                    )}
                    {note && !errors[it.key] && (
                      <span className="text-[11px] leading-relaxed text-tx-faint">{note}</span>
                    )}
                    {st === "running" && <span className="text-[11px] text-tx-faint">Applying…</span>}
                    {st === "card" && <span className="text-[11px] text-tx-faint">Waiting for card payment…</span>}
                  </span>
                  <span className="flex flex-none flex-col items-end gap-0.5">
                    <span className="num text-[12.5px] font-bold text-tx">{fmtMoney(it.dueCents)}</span>
                    {it.dueCents > 0 && (
                      <span className="num text-[10px] text-tx-faint">
                        {cardCents > 0 && walletApplied > 0
                          ? `${fmtMoney(walletApplied)} wallet + ${fmtMoney(cardCents)} card`
                          : cardCents > 0
                            ? "on card"
                            : "from wallet"}
                      </span>
                    )}
                    <span className="num text-[10px] text-tx-faint">+{fmtMoney(it.monthlyCents)}/mo</span>
                  </span>
                </li>
              );
            })}
          </ul>

          {/* ── how to pay ───────────────────────────────────────────────── */}
          <div className="mt-4">
            <span className="text-[10px] font-bold uppercase tracking-[0.14em] text-tx-faint">Pay with</span>
            <div className="mt-2 grid gap-2 sm:grid-cols-2">
              <MethodButton
                on={useWallet}
                disabled={walletBalanceCents <= 0 || busy}
                icon="layers"
                title="Wallet balance"
                sub={
                  walletBalanceCents <= 0
                    ? "No balance — top up first"
                    : `${fmtMoney(walletBalanceCents)} available`
                }
                onClick={() => setUseWallet(true)}
              />
              <MethodButton
                on={!useWallet}
                disabled={busy}
                icon="card"
                title="Credit or debit card"
                sub="Secure Stripe checkout, on this page"
                onClick={() => setUseWallet(false)}
              />
            </div>
            {useWallet && onCard > 0 && (
              <p className="mt-2 text-[11.5px] leading-relaxed text-tx-faint">
                Your balance covers {fmtMoney(fromWallet)} of this; the remaining {fmtMoney(onCard)} goes on
                a card at checkout.
              </p>
            )}
            {!useWallet && items.some((i) => i.walletOnly) && (
              <p className="mt-2 text-[11.5px] leading-relaxed text-amber">
                One of these changes has no card path on our side yet and can only be paid from your wallet
                balance — it is marked above.
              </p>
            )}
            {shortfall > 0 && (
              <p className="mt-2 text-[11.5px] leading-relaxed text-amber">
                Your balance is {fmtMoney(shortfall)} short of what has to come from the wallet. Top up
                first, or remove that change.
              </p>
            )}
          </div>

          {/* ── totals ───────────────────────────────────────────────────── */}
          <dl className="mt-4 flex flex-col gap-1.5 rounded-[12px] border border-rim-soft bg-well px-3.5 py-3">
            <Total label="Due now" value={fmtMoney(dueNow)} strong />
            {fromWallet > 0 && <Total label="From wallet balance" value={`− ${fmtMoney(fromWallet)}`} />}
            {onCard > 0 && <Total label="On card" value={fmtMoney(onCard)} />}
            <div className="mt-1 border-t border-rim-soft pt-1.5">
              <Total
                label={`Renewal, every ${renewalLabel}`}
                value={fmtMoney(renewalAfterCents)}
                was={renewalAfterCents !== renewalBeforeCents ? fmtMoney(renewalBeforeCents) : undefined}
                strong
              />
            </div>
          </dl>

          {/* ── the honest bit ───────────────────────────────────────────── */}
          <p className="mt-3.5 flex items-start gap-2 rounded-[11px] border border-rim-soft px-3 py-2.5 text-[11px] leading-relaxed text-tx-faint">
            <Icon name="warncircle" size={13} tone="inherit" className="mt-[1px] flex-none" />
            Each change is its own operation and this server runs one at a time, so we apply them in the
            order above and you confirm payment once per change. Nothing is charged for a change until that
            change is accepted.
          </p>
        </div>

        <div className="relative z-[1] flex flex-none items-center justify-end gap-2 border-t border-rim-soft px-4 py-3">
          <button
            type="button"
            onClick={() => !busy && onClose()}
            disabled={busy}
            className="rounded-[10px] border border-rim-hi px-3.5 py-2 text-[12.5px] font-semibold text-tx-dim transition hover:text-tx disabled:opacity-40"
          >
            {allDone ? "Close" : "Cancel"}
          </button>
          <button
            type="button"
            onClick={pay}
            disabled={busy || allDone || items.length === 0}
            className="nx-cta px-5 py-2.5 text-[13px] disabled:cursor-not-allowed disabled:opacity-45"
          >
            {busy
              ? "Working…"
              : allDone
                ? "All applied"
                : onCard > 0
                  ? `Pay ${fmtMoney(onCard)} by card`
                  : dueNow > 0
                    ? `Pay ${fmtMoney(dueNow)} from wallet`
                    : "Apply changes"}
          </button>
        </div>
      </div>

      {checkout && (
        <StripeCheckoutModal
          clientSecret={checkout.clientSecret}
          publishableKey={checkout.publishableKey}
          title={checkout.title}
          onClose={() => { setCheckout(null); router.refresh(); }}
        />
      )}
    </div>
  );
}

function MethodButton({ on, disabled, icon, title, sub, onClick }: {
  on: boolean; disabled?: boolean; icon: string; title: string; sub: string; onClick: () => void;
}) {
  return (
    <button
      type="button"
      disabled={disabled}
      aria-pressed={on}
      onClick={onClick}
      className={
        "flex items-center gap-2.5 rounded-[12px] border px-3 py-2.5 text-left transition " +
        (on
          ? "border-[#8b5cff]/65 bg-[color-mix(in_srgb,var(--color-violet)_14%,transparent)]"
          : "border-rim-soft hover:border-rim-hi") +
        (disabled ? " cursor-not-allowed opacity-45" : "")
      }
    >
      <Icon name={icon} size={17} tone="inherit" className={"flex-none " + (on ? "text-[#b08bff]" : "text-tx-faint")} />
      <span className="flex min-w-0 flex-col">
        <span className="truncate text-[12.5px] font-bold text-tx">{title}</span>
        <span className="truncate text-[10.5px] text-tx-faint">{sub}</span>
      </span>
    </button>
  );
}

function Total({ label, value, was, strong }: { label: string; value: string; was?: string; strong?: boolean }) {
  return (
    <div className="flex items-baseline justify-between gap-3">
      <dt className={"text-[12px] " + (strong ? "font-bold text-tx-body" : "text-tx-dim")}>{label}</dt>
      <dd className="flex items-baseline gap-2">
        {was && <span className="num text-[11px] text-tx-faint line-through">{was}</span>}
        <span key={value} className={"num nx-pop " + (strong ? "text-[14px] font-extrabold text-tx" : "text-[12px] text-tx-body")}>
          {value}
        </span>
      </dd>
    </div>
  );
}

