html[data-theme="light"] .nx-dark-island {
  color-scheme: dark;

  --color-void: #00060f;
  --color-bg: #000816;
  --color-surface: #010f22;
  --color-well: #000c1e;
  --color-hover: #021428;
  --color-side: #00081a;
  --color-rim: #002049;
  --color-rim-soft: #00173b;
  --color-rim-hi: #002a5e;

  /* Missed the first time: anything inside the rail or top bar using
     bg-navy-900/whatever (the currency switcher, among others) fell through
     to the ROOT light-theme navy value — near-white — at whatever opacity the
     component asked for, over a dark header. That reads as a grey smear,
     which is exactly the reported bug. */
  --color-navy-950: #000816;
  --color-navy-900: #010f22;
  --color-navy-850: #021428;
  --color-navy-800: #00152f;
  --color-navy-700: #002049;
  --color-navy-600: #002a5e;
  --color-white: #ffffff;

  --color-brand-500: #8c3ae9;
  --color-brand-400: #a05cf0;
  --color-brand-300: #b785f2;
  --color-accent-blue: #2f7eef;
  --color-accent-cyan: #14c5e4;
  --color-cyan: #14c5e4;
  --color-blue: #2f7eef;
  --color-violet: #8c3ae9;
  --color-magenta: #d623e1;
  --color-mint: #11c88e;
  --color-amber: #efa828;
  --color-rose: #ef426c;

  --color-slate-50: #ffffff;
  --color-slate-100: #eaf2ff;
  --color-slate-200: #d8e6ff;
  --color-slate-300: #cbdcff;
  --color-slate-400: #93aede;
  --color-slate-500: #7f9ad0;
  --color-slate-600: #5f7cb4;
  --color-slate-700: #2b4a80;
  --color-slate-800: #001a3d;
  --color-slate-900: #00102a;

