const avail = running;
const s = walletSplit({ dueCents: it.dueCents, balanceCents: avail, useWallet });
running = Math.max(0, running - s.walletApplied);
return {
  it,
  walletApplied: s.walletApplied,
  cardCents: s.cardCents,
  /* `belowStripeMin` is the one state where walletApplied may EXCEED the
     balance — it is what MUST come from the wallet, not what the wallet can
     cover. See lib/wallet-split.ts. */
