input.content:
"use client";

import { useMemo, useState } from "react";
import { Icon } from "@/components/nx/Icon";
import { fmtBytes, fmtMoney } from "@/components/ui/primitives";

import { resizeServer } from "@/lib/actions-server";
import { expandServerDisk } from "@/lib/actions-disk";
import { purchaseDedicatedIp } from "@/lib/actions-dedicated-ip";
import { upgradeServerBackupTier } from "@/lib/actions-backup";

import { prorateUpgradeCents, remainingMonths } from "@/lib/proration";
import {
  EXTRA_DISK_ONE_WAY_NOTE,
  effectiveDiskGB,
  extraDiskCentsAt,
  extraDiskProrateCents,
  maxAddableExtraDiskGB,
  normalizeExtraDiskGB,
} from "@/lib/extra-disk";
import {
  renewalCharge,
  type PricedServer,
  type RenewalPrices,
} from "@/lib/renewal-charge";
import { BACKUP_PLUS_KEEP, backupTierSpec, type BackupTier } from "@/lib/backup-tiers";

import { Panel } from "./kit";
import { VpsPlanChart, type ResourcePlanRow } from "./VpsPlanChart";
import { VpsStorageMeter } from "./VpsStorageMeter";
import { VpsAddonsCard, type AddonOption } from "./VpsAddonsCard";
import { VpsUpgradeCart, type CartItem } from "./VpsUpgradeCart";
import type { VpsHeaderData } from "./types";

/**
 * Resources — what this server is built from, and what it could be.
 *
 * REBUILT FROM SCRATCH. The previous version was a header and a three-way tab
 * switcher (Plan / Storage / Network) painted with literal dark gradients that
 * had no light-theme answer at all, wrapping three self-contained controls that
 * each owned their own price, their own wallet checkbox and their own checkout
 * button. Three separate purchase flows on one screen meant the one question a
 * customer actually has — "what does all of this cost me?" — had no answer
 * anywhere on the page.
 *
 * So the controls became CONTROLLED: they select, and nothing else. This
 * component owns every figure, derives each of them exactly once through the
 * functions the server charges through (`prorateUpgradeCents`,
 * `extraDiskProrateCents`, `renewalCharge`), and hands the selection to one
 * cart and one checkout sheet.
 *
 * NOTHING HERE IS INVENTED. Every purchasable thing on this page maps to a real
 * server action; the add-on card offers exactly the two upgrades that have one
 * (see VpsAddonsCard's header), and the renewal projection is `renewalCharge`
 * — the single renewal formula — evaluated against the selected state, not an
 * estimate beside it.
 */

/* ── the usage rail ───────────────────────────────────────────────────────
   Every bar is a real measurement. An unmeasured one draws an em dash and a
   reason, never an empty bar, which would read as "nothing used". */
function UsageBar({ label, used, total, unit, tone, note }: {
  label: string;
  used: number | null;
  total: number | null;
  unit: (n: number) => string;
  tone: string;
  note?: string;
}) {
  const known = used !== null && total !== null && total > 0;
  const p = known ? Math.max(0, Math.min(100, (used / total) * 100)) : 0;
  return (
    <div className="flex flex-col gap-1.5">
      <div className="flex items-baseline justify-between gap-2">
        <span className="text-[12px] text-tx-dim">{label}</span>
        {used === null ? (
          <span className="num text-[12px] font-bold text-tx-dim">—</span>
        ) : (
          <span className="num text-[12px] font-bold text-tx">{known ? `${Math.round(p)}%` : unit(used)}</span>
        )}
      </div>
      <span className="block h-[5px] w-full overflow-hidden rounded-full bg-[color-mix(in_srgb,var(--fg)_10%,transparent)]">
        {known && <span className="block h-full rounded-full transition-[width] duration-700 ease-out" style={{ width: `${p}%`, background: tone }} />}
      </span>
      {(note || known) && (
        <span className="text-[10.5px] text-tx-faint">{note ?? `${unit(used!)} of ${unit(total!)}`}</span>
      )}
    </div>
  );
}

/* ── the animated summary ─────────────────────────────────────────────────
   Re-keyed on its own value so a change replays `nx-pop` — the transition is
   the one already used everywhere else in this redesign, not a new dependency. */
function Fig({ value, className = "" }: { value: string; className?: string }) {
  return <span key={value} className={"num nx-pop inline-block " + className}>{value}</span>;
}

function SummaryRow({ label, from, to }: { label: string; from: string; to: string }) {
  const changed = from !== to;
  return (
    <div className="flex items-baseline justify-between gap-3 border-t border-rim-soft py-1.5 first:border-t-0 first:pt-0">
      <span className="text-[11.5px] text-tx-dim">{label}</span>
      <span className="flex items-baseline gap-1.5">
        {changed && <span className="num text-[10.5px] text-tx-faint line-through">{from}</span>}
        <Fig value={to} className={changed ? "text-[12.5px] font-bold text-mint" : "text-[12.5px] font-bold text-tx-body"} />
      </span>
    </div>
  );
}

export function VpsResourcesPanel({
  data, serverId, hostname,
  plans, currentPlanId, baseDiskGB, extraDiskGB, extraDiskPerGbCents,
  dedicatedIp, backups, billing, renewal, disabled, disabledReason,
}: {
  data: VpsHeaderData;
  serverId: string;
  hostname: string;

  plans: ResourcePlanRow[];
  currentPlanId: string;
  /** The plan's own disk allowance today — the game-aware base, not `plan.diskGB`. */
  baseDiskGB: number;
  extraDiskGB: number;
  extraDiskPerGbCents: number;

  dedicatedIp: { owned: boolean; monthlyCents: number };
  backups: {
    tier: BackupTier;
    plusMonthlyCents: number;
    /** Quoted SERVER-side by backupUpgradeQuote; null when it could not be quoted. */
    prorateCents: number | null;
    /** False for game servers, which renewalCharge prices flat with no add-on lines. */
    eligible: boolean;
  };

  billing: {
    expiresAt: string | null;
    termMonths: number;
    termPromoPercent: number | null;
    annualDiscountPct: number;
    isFree: boolean;
    walletBalanceCents: number;
  };

  /** Inputs for `renewalCharge` — the ONE renewal formula — as it stands today. */
  renewal: { priced: PricedServer; prices: RenewalPrices };

  disabled?: boolean;
  /** Why the controls are withheld, when they are. */
  disabledReason?: string | null;
}) {
  const ordered = useMemo(() => [...plans].sort((a, b) => a.priceCents - b.priceCents), [plans]);
  const current = ordered.find((p) => p.id === currentPlanId) ?? ordered[0];

  const [planId, setPlanId] = useState<string | null>(null);
  const [addGB, setAddGB] = useState(0);
  const [addons, setAddons] = useState<Record<string, boolean>>({});

  const targetPlan = planId ? ordered.find((p) => p.id === planId) ?? null : null;
  const wantIp = !dedicatedIp.owned && !!addons.ip;
  const wantBackups = backups.eligible && backups.tier === "FREE" && !!addons.backups;

  /* ── money, derived once ────────────────────────────────────────────────
     Not one figure below is a second derivation. `remainingMonths`,
     `prorateUpgradeCents` and `extraDiskProrateCents` are the same functions
     resizeQuote / diskExpandQuote / dedicatedIpPurchaseQuote charge through, and
     the backup proration is not computed here at all — it is quoted on the
     server by `backupUpgradeQuote` and handed in. */
  const months = billing.expiresAt ? remainingMonths(new Date(billing.expiresAt), Date.now()) : 0;
  const chargeable = !billing.isFree && !!billing.expiresAt;

  const planProrate =
    targetPlan && chargeable
      ? prorateUpgradeCents({
          fromMonthlyCents: current.priceCents,
          toMonthlyCents: targetPlan.priceCents,
          termMonths: billing.termMonths,
          termPromoPercent: billing.termPromoPercent,
          annualDiscountPct: billing.annualDiscountPct,
          monthsRemaining: months,
        })
      : 0;

  const maxAddGB = maxAddableExtraDiskGB(baseDiskGB, extraDiskGB);
  /* Round DOWN to a purchasable amount, exactly as `expandServerDisk` does, so
     the figure quoted here can never be lower than the one charged. */
  const buyGB = normalizeExtraDiskGB(addGB);
  const storageMonthly = extraDiskCentsAt(buyGB, extraDiskPerGbCents);
  const storageProrate = chargeable ? extraDiskProrateCents(storageMonthly, months) : 0;

  const ipProrate = wantIp && chargeable ? extraDiskProrateCents(dedicatedIp.monthlyCents, months) : 0;
  const backupProrate = wantBackups ? backups.prorateCents ?? 0 : 0;

  /* ── the renewal, projected ─────────────────────────────────────────────
     `renewalCharge` is the single renewal formula (lib/renewal-charge.ts), and
     it is a pure module precisely so a client surface can evaluate it and show
     what WILL be charged rather than an approximation of it. Current and
     projected both come out of the same call with the same prices. */
  const currentRenewal = useMemo(() => renewalCharge(renewal.priced, renewal.prices), [renewal]);
  const projectedRenewal = useMemo(
    () =>
      renewalCharge(
        {
          ...renewal.priced,
          plan: { ...renewal.priced.plan, priceCents: targetPlan ? targetPlan.priceCents : renewal.priced.plan.priceCents },
          extraDiskGB: renewal.priced.extraDiskGB + buyGB,
          dedicatedIp: renewal.priced.dedicatedIp || wantIp ? true : null,
          backupTier: wantBackups ? "PLUS" : renewal.priced.backupTier,
        },
        renewal.prices,
      ),
    [renewal, targetPlan, buyGB, wantIp, wantBackups],
  );

  /* ── the cart ───────────────────────────────────────────────────────────
     Each line runs the REAL action it names. Nothing here bundles the charge —
     see VpsUpgradeCart's header for why that is not on the table today. */
  const items: CartItem[] = [];
  if (targetPlan) {
    items.push({
      key: "plan",
      icon: "cpu",
      label: `Upgrade to ${targetPlan.name}`,
      detail:
        `${current.cpuCores} → ${targetPlan.cpuCores} vCPU, ` +
        `${Math.round(current.ramMB / 1024)} → ${Math.round(targetPlan.ramMB / 1024)} GB memory, ` +
        `${current.diskGB} → ${targetPlan.diskGB} GB plan disk.`,
      warn: "The server is power-cycled to apply a resize, and a larger plan is permanent.",
      monthlyCents: Math.max(0, targetPlan.priceCents - current.priceCents),
      dueCents: planProrate,
      checkoutTitle: "Complete your upgrade",
      run: (useWallet) => resizeServer(serverId, targetPlan.id, useWallet),
    });
  }
  if (buyGB > 0) {
    items.push({
      key: "storage",
      icon: "database",
      label: `Add ${buyGB} GB storage`,
      detail: `Root disk grows from ${effectiveDiskGB(baseDiskGB, extraDiskGB)} GB to ${effectiveDiskGB(baseDiskGB, extraDiskGB) + buyGB} GB, live, with no reboot.`,
      warn: EXTRA_DISK_ONE_WAY_NOTE,
      monthlyCents: storageMonthly,
      dueCents: storageProrate,
      checkoutTitle: "Complete your storage upgrade",
      run: (useWallet) => expandServerDisk(serverId, buyGB, useWallet),
    });
  }
  if (wantIp) {
    items.push({
      key: "ip",
      icon: "nodes",
      label: "Add a dedicated IPv4",
      detail: "This server gets its own public IP — every port reachable directly, with no NAT forwarding.",
      warn: "A short reboot applies the new network configuration.",
      monthlyCents: dedicatedIp.monthlyCents,
      dueCents: ipProrate,
      checkoutTitle: "Complete your dedicated IP purchase",
      run: (useWallet) => purchaseDedicatedIp(serverId, useWallet),
    });
  }
  if (wantBackups) {
    items.push({
      key: "backups",
      icon: "archive",
      label: "Plus backup retention",
      detail: `Keep the last ${BACKUP_PLUS_KEEP} daily backups instead of ${backupTierSpec("FREE").keep}.`,
      monthlyCents: backups.plusMonthlyCents,
      dueCents: backupProrate,
      walletOnly: true,
      checkoutTitle: "Complete your backup upgrade",
      run: () => upgradeServerBackupTier(serverId, "PLUS"),
    });
  }

  const dueNow = items.reduce((n, i) => n + i.dueCents, 0);

  /* ── add-on rows ────────────────────────────────────────────────────────
     Only what has a server action behind it. `blockedReason` is for a real,
     temporary obstacle (the quote could not be taken because the server is
     busy) — never for something we simply do not sell. */
  const addonOptions: AddonOption[] = [
    {
      key: "ip",
      icon: "nodes",
      ink: "text-[#8fb6ff]",
      title: "Dedicated IPv4",
      blurb: "Your own public IP instead of shared NAT — every port reachable directly, no forwarding.",
      monthlyCents: dedicatedIp.monthlyCents,
      prorateCents: dedicatedIp.owned || !chargeable ? 0 : extraDiskProrateCents(dedicatedIp.monthlyCents, months),
      owned: dedicatedIp.owned,
    },
  ];
  if (backups.eligible) {
    addonOptions.push({
      key: "backups",
      icon: "archive",
      ink: "text-[#3fd6a4]",
      title: "Plus backup retention",
      blurb: `Keep a full week of daily restore points (${BACKUP_PLUS_KEEP}) instead of the included ${backupTierSpec("FREE").keep}.`,
      monthlyCents: backups.plusMonthlyCents,
      prorateCents: backups.prorateCents,
      owned: backups.tier !== "FREE",
      walletOnly: true,
      blockedReason:
        backups.tier === "FREE" && backups.prorateCents === null
          ? "Can't be priced while another operation is running — try again once it finishes."
          : null,
    });
  }

  /* Specs, before and after, for the summary card. */
  const totalDiskNow = effectiveDiskGB(baseDiskGB, extraDiskGB);
  const totalDiskNext = effectiveDiskGB(targetPlan ? targetPlan.diskGB : baseDiskGB, extraDiskGB + buyGB);

  const bwUsed = data.bandwidth.inBytes + data.bandwidth.outBytes;
  const bwAllowance = data.bandwidth.allowanceTB * 1024 ** 4;

  return (
    <div className="flex min-w-0 flex-col gap-4">
      {/* ── hero ─────────────────────────────────────────────────────────── */}
      <section className="card card-glass p-4 sm:p-5" style={{ ["--tone" as string]: "#8b5cff" }}>
        <div className="relative z-[1] flex flex-wrap items-start justify-between gap-4">
          <div className="min-w-0">
            <h2 className="text-[17px] font-extrabold tracking-[-0.01em] text-tx">Upgrade resources</h2>
            <p className="mt-1 max-w-[74ch] text-[12.5px] leading-relaxed text-tx-faint">
              Pick what you want to change. Nothing is charged until you check out, and every figure here
              is computed by the same code that takes the money.
            </p>
          </div>
          <div className="flex flex-none flex-wrap gap-2">
            <span className="rounded-[10px] border border-rim-hi bg-well px-3 py-1.5 text-[11.5px] font-bold text-tx-dim">
              Plan <span className="text-tx">{current?.name ?? data.planName}</span>
            </span>
            <span className="rounded-[10px] border border-rim-hi bg-well px-3 py-1.5 text-[11.5px] font-bold text-tx-dim">
              Renews{" "}
              <span className="num text-tx">
                {billing.isFree ? "free" : `${fmtMoney(currentRenewal.totalCents)} / ${currentRenewal.months === 1 ? "1 month" : `${currentRenewal.months} months`}`}
              </span>
            </span>
          </div>
        </div>

        {disabled && (
          <p className="relative z-[1] mt-3.5 flex items-start gap-2 rounded-[11px] border border-amber/35 bg-amber/10 px-3 py-2.5 text-[11.5px] leading-relaxed text-amber">
            <Icon name="warncircle" size={13} tone="inherit" className="mt-[1px] flex-none" />
            {disabledReason ?? "Changes are paused while another operation runs on this server."}
          </p>
        )}
      </section>

      <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_minmax(0,310px)]">
        {/* ── the controls ───────────────────────────────────────────────── */}
        <div className="flex min-w-0 flex-col gap-4">
          <VpsPlanChart
            plans={ordered}
            currentPlanId={currentPlanId}
            currentDiskGB={current?.diskGB ?? baseDiskGB}
            selectedPlanId={planId}
            onSelect={setPlanId}
            disabled={disabled}
          />

          <VpsStorageMeter
            planDiskGB={baseDiskGB}
            extraDiskGB={extraDiskGB}
            perGbCents={extraDiskPerGbCents}
            maxAddGB={maxAddGB}
            addGB={addGB}
            onChange={setAddGB}
            prorateCents={storageProrate}
            disabled={disabled}
          />

          <VpsAddonsCard
            options={addonOptions}
            selected={addons}
            onToggle={(k, on) => setAddons((s) => ({ ...s, [k]: on }))}
            disabled={disabled}
          />
        </div>

        {/* ── the rail ───────────────────────────────────────────────────── */}
        <div className="flex min-w-0 flex-col gap-4">
          <div className="xl:sticky xl:top-4">
            <Panel
              title={items.length ? "After these changes" : "This server"}
              icon="sliders"
              accent={items.length ? "#11c88e" : "#50b4ff"}
              ink={items.length ? "text-[#3fd6a4]" : "text-[#8fb6ff]"}
            >
              <div className="flex flex-col">
                <SummaryRow label="vCPU" from={`${current?.cpuCores ?? data.specs.vcpu}`} to={`${targetPlan?.cpuCores ?? current?.cpuCores ?? data.specs.vcpu}`} />
                <SummaryRow
                  label="Memory"
                  from={`${Math.round((current?.ramMB ?? data.specs.ramMB) / 1024)} GB`}
                  to={`${Math.round((targetPlan?.ramMB ?? current?.ramMB ?? data.specs.ramMB) / 1024)} GB`}
                />
                <SummaryRow label="Disk" from={`${totalDiskNow} GB`} to={`${totalDiskNext} GB`} />
                <SummaryRow
                  label="Bandwidth"
                  from={`${current?.bandwidthTB ?? data.bandwidth.allowanceTB} TB`}
                  to={`${targetPlan?.bandwidthTB ?? current?.bandwidthTB ?? data.bandwidth.allowanceTB} TB`}
                />
                <SummaryRow
                  label="Public IP"
                  from={dedicatedIp.owned ? "Dedicated" : "Shared NAT"}
                  to={dedicatedIp.owned || wantIp ? "Dedicated" : "Shared NAT"}
                />
                {backups.eligible && (
                  <SummaryRow
                    label="Backups"
                    from={backupTierSpec(backups.tier).label}
                    to={backupTierSpec(wantBackups ? "PLUS" : backups.tier).label}
                  />
                )}
              </div>

              <div className="mt-3.5 flex flex-col gap-2 border-t border-rim-soft pt-3.5">
                <div className="flex items-baseline justify-between gap-3">
                  <span className="text-[11.5px] text-tx-dim">Due now</span>
                  <Fig value={fmtMoney(dueNow)} className="text-[17px] font-extrabold text-tx" />
                </div>
                <div className="flex items-baseline justify-between gap-3">
                  <span className="text-[11.5px] text-tx-dim">
                    Renewal, every {currentRenewal.months === 1 ? "month" : `${currentRenewal.months} months`}
                  </span>
                  <span className="flex items-baseline gap-1.5">
                    {projectedRenewal.totalCents !== currentRenewal.totalCents && (
                      <span className="num text-[10.5px] text-tx-faint line-through">
                        {fmtMoney(currentRenewal.totalCents)}
                      </span>
                    )}
                    <Fig
                      value={fmtMoney(projectedRenewal.totalCents)}
                      className={
                        "text-[13.5px] font-bold " +
                        (projectedRenewal.totalCents !== currentRenewal.totalCents ? "text-mint" : "text-tx-body")
                      }
                    />
                  </span>
                </div>
                <p className="text-[10.5px] leading-relaxed text-tx-faint">
                  {billing.isFree
                    ? "This server is not billed, so nothing here carries a charge."
                    : !billing.expiresAt
                      ? "This server has no term end recorded, so there is nothing to prorate against."
                      : items.length === 0
                        ? "Pick a change to see what it costs."
                        : `Priced over the ${months < 1 ? "part of a month" : `${months.toFixed(1)} months`} still left on your term.`}
                </p>
              </div>
            </Panel>
          </div>

          <Panel title="Current usage" icon="activity" accent="#3fbcd8" ink="text-[#5fd0ff]">
            <div className="flex flex-col gap-3.5">
              <UsageBar
                label="CPU"
                used={data.live ? data.live.cpuPct : null}
                total={data.live ? 100 : null}
                unit={(n) => `${n.toFixed(1)}%`}
                tone="linear-gradient(90deg,#34d399,#5fd0ff)"
                note={data.live ? undefined : "Not reported by the hypervisor"}
              />
              <UsageBar
                label="Memory"
                used={data.live ? data.live.memBytes : null}
                total={data.live ? data.live.maxMemBytes : null}
                unit={fmtBytes}
                tone="linear-gradient(90deg,#7b3fef,#c33bea)"
                note={data.live ? undefined : "Not reported by the hypervisor"}
              />
              <UsageBar
                label="Bandwidth"
                used={bwUsed}
                total={bwAllowance}
                unit={fmtBytes}
                tone="linear-gradient(90deg,#f59e0b,#fb7185)"
              />
            </div>
            <p className="mt-3.5 border-t border-rim-soft pt-3 text-[11px] leading-relaxed text-tx-faint">
              Disk usage is read inside the guest and lives on Overview, next to its history.
            </p>
          </Panel>

          <Panel title="Need something else?" icon="lifebuoy" accent="#8b5cff" ink="text-[#b08bff]">
            <p className="text-[12.5px] leading-relaxed text-tx-dim">
              If none of the sizes fit, we can build one to your spec — at the same per-vCPU and per-GB
              rates the catalogue is priced from.
            </p>
            <a
              href="/dashboard/support"
              className="mt-3 inline-flex items-center gap-2 rounded-[10px] border border-rim-hi bg-well px-3 py-2 text-[12.5px] font-semibold text-tx-body transition hover:border-[#8b5cff]/60 hover:text-tx"
            >
              <Icon name="chat" size={14} tone="inherit" className="text-[#7f9ad0]" />
              Ask for a custom plan
            </a>
          </Panel>
        </div>
      </div>

      {/* Clearance so the sticky bar never covers the last card. */}
      {items.length > 0 && <div aria-hidden className="h-[76px] lg:h-[84px]" />}

      <VpsUpgradeCart
        items={items}
        walletBalanceCents={billing.walletBalanceCents}
        renewalBeforeCents={currentRenewal.totalCents}
        renewalAfterCents={projectedRenewal.totalCents}
        renewalLabel={currentRenewal.months === 1 ? "month" : `${currentRenewal.months} months`}
        disabled={disabled}
        disabledReason={disabledReason}
      />
    </div>
  );
}

