/* One panel now owns the whole tab. It used to be a tab switcher wrapping
   three independent controls (VpsPlanSlider / AddStorage / AddDedicatedIp),
   each with its own price, its own wallet toggle and its own checkout — so
   the combined cost of a change was never shown anywhere. The controls are
   controlled now and the panel derives every figure once, through the same
   functions the actions charge through. `renewal` hands it the two arguments
   `renewalCharge` takes, so the projected renewal is the ONE renewal formula
   evaluated against the selection, not a second estimate beside it. */
const settingsResources = (
  <VpsResourcesPanel
    data={vpsHeader}
    serverId={server.id}
    plans={activePlans.map((p) => ({
      id: p.id, name: p.name, cpuCores: p.cpuCores, ramMB: p.ramMB,
      diskGB: p.diskGB, bandwidthTB: p.bandwidthTB, priceCents: p.priceCents,
    }))}
    currentPlanId={server.planId}
    baseDiskGB={baseDiskGB}
    extraDiskGB={server.extraDiskGB}
    extraDiskPerGbCents={extraDiskPriceCents}
    dedicatedIp={{ owned: dedicated, monthlyCents: ipMonthlyCentsLive }}
    backups={{
      tier: server.backupTier,
      plusMonthlyCents: backupPlusCents,
      /* Quoted authoritatively above by backupUpgradeQuote — null when the
         server was busy and the quote threw, which the card reports rather
         than guessing a number. */
      prorateCents: backupUpgradeProrateCents,
      eligible: !server.gamePlanId,
    }}
    billing={{
      expiresAt: server.expiresAt ? server.expiresAt.toISOString() : null,
      termMonths: server.termMonths,
      termPromoPercent: server.termPromoPercent,
      annualDiscountPct: frozenAnnualDiscountPct(server) ?? annualPct,
      isFree: server.isFree,
      walletBalanceCents: user.balanceCents,
    }}
    renewal={{
      priced: {
        termMonths: server.termMonths,
        extraDiskGB: server.extraDiskGB,
        plan: { name: server.plan.name, priceCents: server.plan.priceCents },
        gamePlan: server.gamePlan
          ? { name: server.gamePlan.name, priceCents: server.gamePlan.priceCents, termMonths: server.gamePlan.termMonths }
          : null,
        dedicatedIp: server.dedicatedIp,
        backupTier: server.backupTier,
        annualDiscountPct: server.annualDiscountPct,
      },
      prices: {
        /* The LIVE price, unconditionally — the panel toggles the
           `dedicatedIp` flag above to price "with one" vs "without one", and
           renewalCharge already bills the surcharge only when the flag is
           set. Passing 0 for a server without an IP (as the page's own
           renewQuote does, where nothing is hypothetical) would make the
           projection for adding one silently free. */
        ipMonthlyCents: ipMonthlyCentsLive,
        extraDiskPerGbCents: extraDiskPriceCents,
        backupPlusCents,
        annualDiscountPct: annualPct,
        taxRatePercent: renewTaxCtx.ratePercent,
      },
    }}
    disabled={busy || !steady}
    disabledReason={
      !steady
        ? "This server has to be running or stopped before its resources can change."
        : "Another operation is already running on this server — changes resume when it finishes."
    }
  />
);

