async function setTheme(mode) {
  await page.evaluate((m) => {
    localStorage.setItem("nx-theme", m);
    if (m === "light") document.documentElement.setAttribute("data-theme", "light");
    else document.documentElement.removeAttribute("data-theme");
  }, mode);
}

for (const id of ids) {
  for (const mode of ["dark", "light"]) {
    await page.goto(`${BASE}/dashboard/servers/${id}?tab=settings`, { waitUntil: "networkidle", timeout: 60000 }).catch(() => {});
    await setTheme(mode);
    await page.reload({ waitUntil: "networkidle" }).catch(() => {});
    await page.waitForTimeout(2200);
    await page.screenshot({ path: join(out, `${id}-${mode}-rest.png`), fullPage: true });

    // Now fill the cart: pick the most expensive pickable plan, drag storage,
    // tick every available add-on.
    const picked = await page.evaluate(() => {
      const bars = [...document.querySelectorAll('button[aria-pressed]')].filter(
        (b) => b.textContent?.includes("vCPU") && !b.disabled,
      );
      if (bars.length) { bars[bars.length - 1].click(); return bars.length; }
      return 0;
    });
    const range = page.locator('input[aria-label="Extra storage to add, in GB"]');
    if (await range.count()) {
      await range.first().evaluate((el) => {
        const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, "value").set;
        setter.call(el, "100");
        el.dispatchEvent(new Event("input", { bubbles: true }));
        el.dispatchEvent(new Event("change", { bubbles: true }));
      });
    }
    await page.evaluate(() => {
      for (const b of document.querySelectorAll('li > button[aria-pressed="false"]')) {
        if (!b.disabled) b.click();
      }
    });
    await page.waitForTimeout(1400);
    await page.screenshot({ path: join(out, `${id}-${mode}-cart.png`), fullPage: true });

    // And the checkout sheet.
    const btn = page.locator('button', { hasText: /^Checkout$/ });
    if (await btn.count()) {
      await btn.first().click({ timeout: 5000 }).catch(() => {});
      await page.waitForTimeout(1200);
      await page.screenshot({ path: join(out, `${id}-${mode}-checkout.png`) });
    }
    console.log(`${id} ${mode} (plan buttons: ${picked})`);
  }
}

await browser.close();

